INSERT INTO `quotation` (`id`, `guest_name`, `ref_name`, `mobile_no`, `email`, `destination`, `tentative_date`, `nights`, `children`, `adults`, `itineraries`, `flights`, `trains`, `hotels`, `terms_conditions`, `children_ages`, `inclusion`, `exclusion`, `payment_policy`, `cancellation_policy`, `costing`, `ref_id`, `total`, `adult_cost`, `child_cost`, `created_at`, `updated_at`, `is_confirmed`, `hide_note`, `other_details`, `is_feedback_sent`, `is_feedback_received`) VALUES
(4, 'Sunshine International Tours & Travels', NULL, '9880262392', NULL, 'Jharkhand', '2018-06-26', 5, 0, 6, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":null,\"caption\":\"Ranchi Airport to Hazaribagh\",\"date\":\"26-06-2018\",\"todo\":\"Pickup at 9am from Ranchi airport and proceed to Hazaribagh\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":null,\"caption\":\"Hazaribagh - Baidyanath - Hazaribagh\",\"date\":\"27-06-2018\",\"todo\":\"Morning departure from Hazaribagh for day trip to Baidyanath Temple\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":null,\"caption\":\"Hazaribagh - Ranchi\",\"date\":\"28-06-2018\",\"todo\":\"Morning departure from Hazaribagh to Ranchi. In between Rajarapa Temple visit and Patratu valley visit.\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":null,\"caption\":\"Ranchi local\",\"date\":\"29-06-2018\",\"todo\":\"Ranchi local sightseeing which includes Paharimandir, Dasham falls, Birsa Zoo, Rock garden.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":null,\"caption\":\"Airport Drop\",\"date\":\"30-06-2018\",\"todo\":\"Morning drop to airport\"}]', '[]', '[]', '[{\"id\":0,\"city\":\"Ranchi\",\"hotel_name\":\"Hotel Capitol Hill\",\"room_type\":\"Standard Room with Breakfast\",\"check_in\":\"28\\/06\\/2018\",\"check_out\":\"30\\/06\\/2018\",\"rooms\":3,\"nights\":2}]', '<ul>\n	<li>This is just a quote, no reservations held yet or booking is not proceed yet.</li>\n	<li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li>\n	<li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li>\n	<li>The change in dates will attract re-quote.</li>\n	<li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li>\n	<li>5.0% Goods and Services Tax will be applicable against final Invoice (Subject to Payment Made in INR).</li>\n	<li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li>\n	<li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li>\n	<li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li>\n	<li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li>\n	<li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li>\n</ul>', '[]', '<ul>\n	<li>01 Private Innova for all transfers and sightseeings as per the itinerary</li>\n	<li>02 Nights accomodation in Hotel Capitol Hill with breakfast.</li>\n	<li>All tolls and parking charges.</li>\n	<li>Driver allowances</li>\n	<li>All taxes&nbsp;</li>\n</ul>', '<p>Anything not mentioned in the inclusion</p>', NULL, NULL, '{\"package\":{\"land_cost\":\"14000\",\"hotel_cost\":\"32000\"},\"cost_price\":46000,\"profit_percent\":\"0\",\"selling_price\":46000}', 'MZQ/03/062018', 46200, 7700, 0, '2018-06-06 14:58:04', '2018-06-09 12:47:52', 0, 0, NULL, 0, 0),
(8, 'Mrs. Toshi Lall x 02', NULL, '9916000914', 'toshi.lall21@yahoo.com', 'SRI LANKA', '2018-08-14', 5, 0, 2, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521567\\/rf6nyaewp8lxccugdsic.jpg\",\"caption\":\"COLOMBO - KANDY\",\"date\":\"14-08-2018 Tuesday\",\"todo\":\"Special Sri Lanka tour starts on your arrival in Sri Lanka Airport, warmly welcomed by our company representative. We will arrange Local Guide Lecture, Luxury Transport service, Local Sim Cards, Mineral water bottles \\u2013 Proceed to Kandy en-route visiting Pinnawala elephant Orphanage. Check-in the Hotel, \\nOvernight stay at HOTEL SANDRIYANA LAKE VIEW\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521569\\/rzxpzrss6r3erhwreg57.jpg\",\"caption\":\"KANDY LOCAL\",\"date\":\"15-08-2018 Wednesday\",\"todo\":\"Visit Royal Botanical Garden\\/ Temple of Tooth Relic\\/ Gem Museum\\/ Cultural Show.\\nOvernight stay at HOTEL SANDRIYANA LAKE VIEW\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521571\\/cdzp0pzlxmx90vwpqvnx.jpg\",\"caption\":\"KANDY - NUWARAELIYA\",\"date\":\"16-08-2018 Thursday\",\"todo\":\"Visit Nuwara Eliya City Tour \\/ Victoria Park \\/ Seetha Amman Temple \\/ Gregory Lake \\/ Evening Leisure at Hotel.\\nOvernight stay at Ashford Hotel\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521572\\/lrpxoul8vnzzt4uzvfcu.jpg\",\"caption\":\"NUWARAELIYA - BENTOTA\",\"date\":\"17-08-2018 Friday\",\"todo\":\"Visit Madu River Boat Ride \\/ Turtle Hatchery\\/ Evening Leisure at Beach and Hotel.\\nOvernight stay at Coco Royal Resort.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521574\\/hwrvqlmxgoubphw0m88p.jpg\",\"caption\":\"BENTOTA - COLOMBO\",\"date\":\"18-08-2018 Saturday\",\"todo\":\"Today visit  Colombo City tour with Shopping.\\nOvernight stay at Sapphire Hotel\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532521575\\/tsc1jysf8kkgzuzzdtko.jpg\",\"caption\":\"DEPARTURE FROM COLOMBO\",\"date\":\"19-08-2018 Sunday\",\"todo\":\"Pack your bags. \\nTour Ends with Happy Memories.\"}]', '[{\"id\":0,\"from\":\"Bangalore (BLR)\",\"to\":\"Colombo (CMB)\",\"name\":\"SriLankan\",\"fno\":\"174\",\"dep_date\":\"14\\/08\\/2018\",\"arv_date\":\"14\\/08\\/2018\",\"dep_time\":\"03:30 AM\",\"arv_time\":\"05:00 AM\"},{\"id\":1,\"from\":\"Colombo (CMB)\",\"to\":\"Bangalore (BLR)\",\"name\":\"SriLankan\",\"fno\":\"173\",\"dep_date\":\"19\\/08\\/2018\",\"arv_date\":\"19\\/08\\/2018\",\"dep_time\":\"01:05 AM\",\"arv_time\":\"02:30 AM\"}]', '[]', '[{\"id\":0,\"check_in\":\"14\\/08\\/2018\",\"city\":\"KANDY\",\"hotel_name\":\"Sandriana Lake view Hotel\",\"rooms\":1,\"nights\":2,\"check_out\":\"16\\/08\\/2018\",\"room_type\":\"DBL ROOM\"},{\"id\":1,\"city\":\"NUWARAELIYA\",\"hotel_name\":\"Ashford Hotel\",\"room_type\":\"DBL ROOM\",\"rooms\":1,\"nights\":1,\"check_out\":\"17\\/07\\/2018\",\"check_in\":\"16\\/08\\/2018\"},{\"id\":2,\"city\":\"BENTOTA\",\"hotel_name\":\"Coco Royal Resort\",\"room_type\":\"DBL ROOM\",\"rooms\":1,\"nights\":1,\"check_out\":\"18\\/08\\/2018\",\"check_in\":\"17\\/08\\/2018\"},{\"id\":3,\"city\":\"COLOMBO\",\"hotel_name\":\"Sapphire Hotel\",\"room_type\":\"DBL ROOM\",\"rooms\":1,\"nights\":1,\"check_out\":\"19\\/08\\/2018\",\"check_in\":\"18\\/08\\/2018\"}]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quote.</li><li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li><li>5.0% Goods and Services Tax will be applicable against final Invoice (Subject to Payment Made in INR).</li><li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li><li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li><li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li><li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li><li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li></ul>', '[]', '<p>&nbsp;Welcome &amp; assistance at the Colombo International Air Port.</p><p>* Transport in an A/C Luxury Car with the service of an English Speaking Driver as per the itinerary &nbsp;&nbsp;</p><p>* Value added tax.</p><p>* Accommodation at the above mentioned hotel or similar on BB basis.</p><p>* 05 Breakfasts (At Hotel)</p><p>&nbsp;</p><p><b><u>Value added services by Multi Zone&nbsp;Travels</u></b></p><p>* Complementary Entrance for Spice Garden</p><p>* Complementary Entrance for Gem Museum</p><p>* Complementary Entrance for Cultural Show</p><p>* Discount Shopping Card Coupon Per Person (Colombo)</p><p>* Complementary Sim Cards</p>', '<ul><li>Lunch and Dinner on tour.</li></ul><ul><li>Entrance fees&nbsp;for Indian passport holders,</li></ul><p>&nbsp;</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Pinnawala Elephant Orphanage&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -$ 6 Per Adult</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Kandy Temple of Tooth Relic&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -$ 7 Per Adult&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Peradaniya Botanical Gardens&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-$ 11 Per Adult</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Victoria Park&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-$ 5 Per Adult</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Gangarama Temple Colombo&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -$ 5 Per Adult&nbsp;</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Cultural show&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-This ticket free from us</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Water sports&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(01 Jet Ski / 01 Banana Boat Ride / 01 Tube Boat Ride / 01 River Safari)&nbsp;&nbsp;Price Depends&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Turtle hatchery&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-$ 4 Per Adult&nbsp;</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Madu river boat ride&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-$ 16 Per boat&nbsp;<i>(Can accommodate 06 Pax in a Boat)</i></b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>Gregory Lake,Entrance&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -$ 2 Per Adult</b></p><p>* Camera &amp; Video permits.&nbsp;</p><p>* Any expenses of personal nature.</p><p>* Any other expenses not mentioned above.</p><p>* Any other entrance fee not mentioned above (Relevant to particular places)</p><p>* The vehicle will not be provide for the night life and for the casinos. &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br />* Early Check in &amp; Late Checkout.</p><p>* Bank surcharges.</p><p>* Tips &amp; Portages.</p>', NULL, NULL, '{\"profit_percent\":\"17\",\"package\":{\"flight_cost\":\"26306\",\"land_cost\":\"37886\"},\"cost_price\":64192,\"selling_price\":75104.639999999999417923390865325927734375}', 'MZQ/06/072018', 77000, 38500, 0, '2018-07-25 12:26:16', '2018-09-29 11:21:08', 0, 0, NULL, 0, 0),
(9, 'Dr. S. Karim x 03', 'Mr. P.K. Jha', '8986893768', 'pkjhaohc@gmail.com', 'DUBAI', '2018-08-23', 4, 0, 3, '[]', '[{\"id\":0,\"from\":\"Patna (PAT)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"6367\",\"dep_date\":\"23\\/08\\/2018\",\"arv_date\":\"23\\/08\\/2018\",\"dep_time\":\"09:05 AM\",\"arv_time\":\"10:55 AM\"},{\"id\":1,\"from\":\"Delhi (DEL)\",\"to\":\"Dubai (DXB)\",\"name\":\"IndiGo\",\"fno\":\"21\",\"dep_date\":\"23\\/08\\/2018\",\"arv_date\":\"23\\/08\\/2018\",\"dep_time\":\"05:10 PM\",\"arv_time\":\"07:25 PM\"},{\"id\":2,\"from\":\"Dubai (DXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"22\",\"dep_date\":\"27\\/08\\/2018\",\"arv_date\":\"28\\/08\\/2018\",\"dep_time\":\"10:20 PM\",\"arv_time\":\"03:00 AM\"},{\"id\":3,\"from\":\"Delhi (DEL)\",\"to\":\"Patna (PAT)\",\"name\":\"IndiGo\",\"fno\":\"634\",\"dep_date\":\"28\\/08\\/2018\",\"arv_date\":\"28\\/08\\/2018\",\"dep_time\":\"06:35 AM\",\"arv_time\":\"09:15 AM\"}]', '[]', '[{\"id\":0,\"check_in\":\"23\\/08\\/2018\",\"city\":\"DUBAI\",\"hotel_name\":\"HOLIDAY INN BUR DUBAI\",\"room_type\":\"STANDARD ROOM (BB)\",\"rooms\":1,\"nights\":4,\"check_out\":\"27\\/08\\/2018\"}]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quote.</li><li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li><li>5.0% Goods and Services Tax will be applicable against final Invoice (Subject to Payment Made in INR).</li><li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li><li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li><li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li><li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li><li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li></ul>', '[]', '<table border=\"0\" cellpadding=\"0\" width=\"100%\"><tbody><tr><td><ol type=\"1\"><li>RETURN FLIGHT TICKET EX- PATNA</li><li>ROYAL PRIVATE AIRPORT TRANSFER (PRIVATE TRANSFER )&nbsp;</li><li>ROYAL PRIVATE AIRPORT TRANSFER (PRIVATE TRANSFER )&nbsp;</li><li>TRIO COMBO ON SIC TRANS (DUBAI CITY TOUR/ DESERT SAFARI/ DHOW CRUISE)&nbsp;</li><li>AT THE TOP BURJ KHALIFA ENTRY TICKET</li><li>PVT TRANSFER - AT THE TOP BURJ KHALIFA&nbsp;</li><li>OK TO BOARD CHARGES</li><li>TOURIST VISA</li></ol></td></tr></tbody></table>', '<table border=\"0\" cellpadding=\"0\" width=\"100%\"><tbody><tr><td><p><b><u>TOURISM DIRHAM:</u></b></p><p>Please note Dubai Government has introduced “TOURISMDIRHAM FEES” on all guest staying in Dubai effective 01<sup>st</sup>&nbsp;Apr 2014.Details of charges are given in schedule mentioned below.</p><p>These taxes will be charged to guest in addition to the package cost mentioned above.</p><table border=\"0\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td width=\"233\" valign=\"top\"><p><b>Hotel /Apartment Categories</b></p></td><td width=\"318\" valign=\"top\"><p><b>Tourism Dirham Fee</b></p></td></tr><tr><td width=\"233\" valign=\"top\"><p>***** Hotels</p></td><td width=\"318\" valign=\"top\"><p>AED 20 Per Bed Room Per Night</p></td></tr><tr><td width=\"233\" valign=\"top\"><p>**** Hotels</p></td><td width=\"318\" valign=\"top\"><p>AED 15 Per Bed Room Per Night</p></td></tr><tr><td width=\"233\" valign=\"top\"><p>*** Hotels</p></td><td width=\"318\" valign=\"top\"><p>AED 10 Per Bed Room Per Night</p></td></tr><tr><td width=\"233\" valign=\"top\"><p>Deluxe Hotel Apartment</p></td><td width=\"318\" valign=\"top\"><p>AED 20 Per Bed Room Per Night</p></td></tr><tr><td width=\"233\" valign=\"top\"><p>Superior Hotel Apartment</p></td><td width=\"318\" valign=\"top\"><p>AED 15 Per Bed Room Per Night</p></td></tr><tr><td width=\"233\" valign=\"top\"><p>Standard Hotel Apartment</p></td><td width=\"318\" valign=\"top\"><p>AED 10 Per Bed Room Per Night</p></td></tr></tbody></table></td></tr><tr><td><p><b><u>HOTEL STANDARD CHECK IN AND CHECKOUT TIME:</u></b></p><p>Check in: 1400hrs &amp; Check-out: 1200hrs (Check in&amp; Check out time varies with different Hotels &amp; Apartments)</p></td></tr><tr><td><p><b><u>VISA NOTE:</u></b></p><p>The Entire accommodation in UAE should be booked and confirmed through Multi Zone Travels to issue the VISA. As per the new Immigration rule all tourism agencies are required to attach accompanies passport copy and birth certificate with the visa application for children under the legal age (18 Years). In order to avoid delays with Immigration formalities, we recommend all passengers have per-arranged visas and to proceed with a copy of the visa to the eye-scan counters located in the arrivals hall next to the visa collection counters before approaching Passport Control.Kindly convey this message to your clients.&nbsp;<b>Passport of the passengers should be valid for minimum of 06 months from the date of travel to the U.A.E.&nbsp;.</b></p><p><i>All children under the legal ageof 18 years traveling to UAE should provide following documents toprocess/obtain visa for UAE.</i></p><p>1. Scanned Passport copy.</p><p>2. Scanned Photograph.</p><p>3. Scanned Birth Certificate.</p><p>4. Passport copies of the person the child is traveling with.</p></td></tr></tbody></table>', NULL, NULL, '{\"package\":{\"flight_cost\":\"94375\",\"land_cost\":\"64709\"},\"cost_price\":159084,\"selling_price\":171084,\"profit_figure\":\"12000\"}', 'MZQ/07/072018', 171084, 57028, 0, '2018-07-25 13:04:54', '2018-07-27 06:13:22', 0, 0, NULL, 0, 0),
(10, 'Mr. Kumar Rupesh x 6 Adults & 2 Children', NULL, '8294727527', 'rupesh3004@gmail.com', 'VIETNAM', '2018-10-13', 6, 2, 6, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773648\\/o876fepidylus2ww4ao1.jpg\",\"caption\":\"Arrival in Hanoi\",\"date\":\"13-10-2018 Saturday\",\"todo\":\"Arrival in Hanoi. We welcome you at the airport and transfer you to hotel. Check-in at the hotel. Your free tim in Hanoi. Overnight at the hotel in Hanoi.\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773650\\/vckwwwdksnrmvsmptwf4.jpg\",\"caption\":\"Hanoi \\u2013 City Tour (B,L)\",\"date\":\"14-10-2018 Sunday\",\"todo\":\"After breakfast at 8.30 AM, our tour guide pick you up at hotel to join Hanoi city tour. You will start the tour by visiting Ho Chi Minh Mausoleum and Ho Chi Minh Museum. Enjoy the architectural and historical aspects of Uncle Ho\\u2019s final resting-palace. Just next door is Ho Chi Minh\\u2019s house on stilts where he used to live in the past. Lying to one side of the Mausoleum is the One Pillar Pagoda, built by King Ly Thai To in 1049 the structure has become an important symbol for the people of Hanoi. Continue your visit to the Temple of Literature (Quoc Tu Giam) \\u2013 Vietnam\\u2019s first University constructed in 1070. Its gardens and well-preserved architecture offer a relaxing glimpse into Vietnam\\u2019s past. Have lunch at local restaurants. Proceed to visit the Ethnology Museum. After that we will take you to Hoan Kiem Lake, see the peaceful water, and visit Ngoc Son Temple. Take an hour cyclo tour around the bustling old quarter to see ordinary life in Hanoi. At 18.00, back to your hotel. Stay overnight at hotel in Hanoi.\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773652\\/daoghdm5ppypbkkxi1vb.jpg\",\"caption\":\"Hanoi \\u2013 Halong bay (B,L,D)\",\"date\":\"15-10-2018 Monday\",\"todo\":\"Around 8.00, our guide Pick you up at your hotel and go to Halong bay on a shuttle bus. Take a rest at Humanity center and enjoy local specialties after 2h. Arrival in Halong at 11.45. The captain and crew welcome you aboard. Savor the delicious lunch as boat pass through thousands of Islands and Islets with different shapes. After the lunch, explore the biggest and the most amazing cave in Halong Bay \\u2013Surprise Cave. Then Kayaking for an hour around the fishing village and discover the life of community there. Then back to boat for Sunset Party, get to calm, clean water place for swimming. Enjoy delicious and romantic dinner with some barbecue courses. In the evening, free time for entertainment with the funny plays such as squid fishing, karaoke program, stars watching on sundeck\\u2026 Spend romantic night on board. Stay overnight on board.\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773654\\/crhxcviq4ao8sz5gqbfd.jpg\",\"caption\":\"Halong bay \\u2013 Ho Chi Minh (B,L)\",\"date\":\"16-10-2018 Tuesday\",\"todo\":\"Early morning, start your new day on Halong bay with doing morning exercises,Taichi or hunting photos. Breakfast with coffee or tea. After breakfast, our bus takes you to Cai Beo harbor, get on \\u201cDay Boat\\u201d, back boat. Then visit Ba Hang Fishing Village by tender to experience the lifestyle of local people. Back to boat restaurant to join cooking class and enjoy lunch. Around 11.45 AM, Disembark and transfer back to Hanoi. Transfer you directly to Noi Bai airport (in Hanoi) for the flight to Ho Chi Minh. Arrival in Ho Chi Minh. Check-in room at hotel and stay overnight in Ho Chi Minh.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773656\\/gkntlnbvexkcgakgt0ui.jpg\",\"caption\":\"Ho Chi Minh - city tour and explore Cu Chi Tunnel (B,L)\",\"date\":\"17-10-2018 Wednesday\",\"todo\":\"Morning, at around 8.30 AM, your family start Ho Chi Minh City tour. We start the trip by visiting Notre Dame Cathedral, the historic Central Post Office, followed by exploring the Reunification Palace, and the remarkable site of the War Remnants Museum, (optional Ben Thanh Market \\u2013 only drop off). Afternoon, visit Cu Chi Tunnels. Located 60km from HCMC, Cu Chi is now a popular spot for both Vietnamese & foreign tourists \\u2013 the network of over 200km of tunnels became legendary when they played a vital role in the War. In their heyday, the tunnels were functioning underground cities including numerous trap doors, specially constructed living areas, storage facilities, weapons factories, field hospitals, command centers & kitchens. Stay overnight at hotel in Ho Chi Minh.\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773657\\/wyf3xb9xhiojeq5rx6p6.jpg\",\"caption\":\"Ho Chi Minh city \\u2013 Mekong delta (B,L)\",\"date\":\"18-10-2018 Thursday\",\"todo\":\"Morning, at around 8.30 AM, Leave Ho Chi Minh city, enjoy the scenic journey along the National Highway bordered by green rice fields. On arrived at My Tho, visit Vinh Trang pagoda, take a leisurely boat ride along the river, view stilt houses, fruit plantations and fishing villages along the river bank. Proceed to Tortoise islet, have lunch in the orchard garden. After lunch, take a boat trip to An Khanh \\u2013 a less touristy attraction in Ben Tre, enjoy cruising on a handrowed sampan under the shade of the water coconut trees along natural canals. Have a short cycling tour (applied for private tour\\/if time permitted) then enjoy seasonal fruit & honey tea to the sound of \\u201cSouthern Vietnamese folk music\\u201d, performed by the locals. Visit a family business which epitomizes the idyllic rural lifestyle, taste delicious coconut candy & observe the pastoral life as you roam through fruit plantations and villages. Back to Ho Chi Minh. Stay overnight at hotel in Ho Chi Minh.\"},{\"title\":\"Day\",\"day\":7,\"index\":6,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773659\\/ruytqyv6eynpjrag4ueu.jpg\",\"caption\":\"Ho Chi Minh city \\u2013 Departure (B)\",\"date\":\"19-10-2018 Friday\",\"todo\":\"After breakfast at hotel, your leisure time and you have lunch by yourselves. Our driver comes to the hotel to pick you up after you check out, transfers you to the airport to take the flight back home.\"}]', '[{\"id\":0,\"from\":\"Delhi (DEL)\",\"to\":\"Bangkok (BKK)\",\"name\":\"Thai\",\"fno\":\"332\",\"dep_date\":\"13\\/10\\/2018\",\"arv_date\":\"13\\/10\\/2018\",\"dep_time\":\"03:20 AM\",\"arv_time\":\"09:15 AM\"},{\"id\":1,\"from\":\"Bangkok (BKK)\",\"to\":\"Hanoi (HAN)\",\"name\":\"Thai\",\"fno\":\"564\",\"dep_date\":\"13\\/10\\/2018\",\"arv_date\":\"13\\/10\\/2018\",\"dep_time\":\"05:50 PM\",\"arv_time\":\"07:40 PM\"},{\"id\":2,\"from\":\"Ho Chi Minh (SGN)\",\"to\":\"Kuala-lumpur (KUL)\",\"name\":\"AirAsia Airways\",\"fno\":\"527\",\"dep_date\":\"19\\/10\\/2018\",\"arv_date\":\"19\\/10\\/2018\",\"dep_time\":\"01:25 PM\",\"arv_time\":\"04:20 PM\"},{\"id\":3,\"from\":\"Kuala-lumpur (KUL)\",\"to\":\"Delhi (DEL)\",\"name\":\"AirAsia X Airways\",\"fno\":\"182\",\"dep_date\":\"19\\/10\\/2018\",\"arv_date\":\"19\\/10\\/2018\",\"dep_time\":\"07:05 PM\",\"arv_time\":\"10:00 PM\"}]', '[]', '[{\"id\":0,\"check_in\":\"13\\/10\\/2018\",\"city\":\"Hanoi\",\"hotel_name\":\"La Dolce Vita hotel \\/ La Suite hotel\",\"room_type\":\"DBL\",\"rooms\":3,\"nights\":2,\"check_out\":\"15\\/10\\/2018\"},{\"id\":1,\"city\":\"Ha Long bay\",\"hotel_name\":\"Legend Imperial cruise \\/ V Spirit cruise\",\"room_type\":\"DBL\",\"rooms\":3,\"nights\":2,\"check_out\":\"17\\/10\\/2018\",\"check_in\":\"15\\/10\\/2018\"},{\"id\":2,\"city\":\"Ho Chi Minh City\",\"hotel_name\":\"Ha Hien Signature hotel \\/ Cap Town hotel\",\"room_type\":\"DBL\",\"rooms\":3,\"nights\":2,\"check_out\":\"19\\/10\\/2018\",\"check_in\":\"17\\/10\\/2018\"}]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quote.</li><li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li><li>5.0% Goods and Services Tax will be applicable against final Invoice (Subject to Payment Made in INR).</li><li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li><li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li><li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li><li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li><li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li></ul>', '[{\"age\":6},{\"age\":6}]', '<ul><li>Return Air fare Ex- Delhi</li><li>Hotel/Accommodations.</li><li>Domestic flight</li><li>Kayakking: Safe, clean and nice.</li><li>Room on boat with AirConditioner in Halong bay</li><li>Meals mentioned (B,L,D).</li><li>Transfer as per itinerary.</li><li>English speaking guide.</li><li>Entrance &amp; sightseeing fees.</li></ul>', '<ul><li>Tips</li><li>Visa Charges @ 5500 per pax&nbsp;</li><li>Drinks</li><li>Other private expenses.</li></ul>', NULL, NULL, '{\"profit_percent\":\"12\",\"package\":{\"flight_cost\":\"235967\",\"land_cost\":\"303940\"},\"cost_price\":539907,\"selling_price\":604695.839999999967403709888458251953125}', 'MZQ/08/072018', 605000, 79500, 64000, '2018-07-28 10:27:38', '2018-07-31 05:52:00', 0, 0, NULL, 0, 0),
(11, 'Mr. Kumar Rupesh x 6 Adults & 2 Children', NULL, '8294727527', 'rupesh3004@gmail.com', 'VIETNAM', '2018-10-13', 6, 2, 6, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773648\\/o876fepidylus2ww4ao1.jpg\",\"caption\":\"Arrival in Hanoi\",\"date\":\"13-10-2018 Saturday\",\"todo\":\"Arrival in Hanoi. We welcome you at the airport and transfer you to hotel. Check-in at the hotel. Your free tim in Hanoi. Overnight at the hotel in Hanoi.\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773650\\/vckwwwdksnrmvsmptwf4.jpg\",\"caption\":\"Hanoi \\u2013 City Tour (B,L)\",\"date\":\"14-10-2018 Sunday\",\"todo\":\"After breakfast, we discover the wonders of the capital of Vietnam, filled with timeless charm. Start by visiting Van Mieu (Temple of Literature), the first University of Vietnam built from the 11th century by Emperor Ly Thanh Tong. Continue to visit Chua Ha (Ha Pagoda), known as a sacred place to pray for luck in love.  \\nAfter that, transfer to the Ethnology Museum (closed every Monday) which offers a deep insight into Vietnamese culture through traditional costumes, tools, musical instruments and traditional houses of many minority ethnic groups. Enjoy a special water puppet show in the museum garden. Lunch is served in a local restaurant. In the afternoon, discover the Ho Chi Minh complex including the Presidential Palace, Ho Chi Minh\'s House on stilts and the fish pond.  \\nFor those who are interested in visiting the Ho Chi Minh Mausoleum, it is only open in the morning and closed every Monday and Friday. Sometimes it is necessary to queue for a couple of hours to go inside the mausoleum. Transfer to the old quarter to visit Hoan Kiem lake (Restored Sword Lake) and Ngoc Son temple in the middle of the lake. Overnight in Hanoi\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773652\\/daoghdm5ppypbkkxi1vb.jpg\",\"caption\":\"Hanoi \\u2013 Halong Bay (B\\/L\\/D)\",\"date\":\"15-10-2018 Monday\",\"todo\":\"8.30 am, pick up and transfer to Halong Bay. Embark Cruise followed by a short cruise briefing.  Savor a delectable lunch on cruises among the limestone islands.Explore the amazing Sung Sot Cave \\u2013 the most beautiful cave in Halong Bay. Cruising to Titov island. Go swimming and relaxing at the beach of Titov or climb up to the top of the island for a panorama view of Halong Bay. Return to the main boat and continue cruising to the quiet area while enjoy beautiful seascape on the way. Enjoy Sunset Party on sundeck and admire the best moments of the day when the sun starts to set. Dinner is served. Socialize with other guests, take part in board games, fish for squid, or just laze around.\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773654\\/crhxcviq4ao8sz5gqbfd.jpg\",\"caption\":\"Halong Bay \\u2013 Hanoi (B\\/L\\/-)\",\"date\":\"16-10-2018 Tuesday\",\"todo\":\"Start your day with Tai Chi exercises or a photo hunt. Have breakfast on board and enjoy the peaceful morning of Halong Bay.  Kayak among the hidden areas of the bay, around the Drum Cave. Return to the boat. Freshen up and check out of your cabin. Continue your cruise exploring the Bay, passing Ba Hang fishing village, Dog Islet, and more. While heading back to the harbor, watch the fruit carving demonstration and participate in the Cooking Class before enjoying a traditional Vietnamese lunch. Disembark the cruise and take a transfer back to Hanoi  Overnight in Hanoi.\\nNote: Cruise\\u2019s activities order will be depend on each cruises and tide. It is adjustable.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773656\\/gkntlnbvexkcgakgt0ui.jpg\",\"caption\":\"Hanoi \\u2013 Fly to Ho Chi Minh city tour (B\\/L\\/-)\",\"date\":\"17-10-2018 Wednesday\",\"todo\":\"Morning, at around 8.30 AM, your family start Ho Chi Minh City tour. We start the trip by visiting Notre Dame Cathedral, the historic Central Post Office, followed by exploring the Reunification Palace, and the remarkable site of the War Remnants Museum, (optional Ben Thanh Market \\u2013 only drop off). Afternoon, visit Cu Chi Tunnels. Located 60km from HCMC, Cu Chi is now a popular spot for both Vietnamese & foreign tourists \\u2013 the network of over 200km of tunnels became legendary when they played a vital role in the War. In their heyday, the tunnels were functioning underground cities including numerous trap doors, specially constructed living areas, storage facilities, weapons factories, field hospitals, command centers & kitchens. Stay overnight at hotel in Ho Chi Minh.\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1533015998\\/rmr6nnixmrt5lq7x2abi.jpg\",\"caption\":\"Ho Chi Minh Cu Chi \\u2013 Ho Chi Minh city (B\\/L\\/-)\",\"date\":\"18-10-2018 Thursday\",\"todo\":\"Depart Ho Chi Minh to discover one of the most striking places in the history of the Vietnam War, the Cu Chi Tunnels.  \\nCu Chi is a real underground city made up of a large network of tunnels covering an area of over 250 km where the Viet Cong conducted the war of resistance against American troops. All of the tunnels were dug by the Viet Cong over a period of twenty years using only pickaxes and shovels. You will also have a chance to visit Ben Duoc memorial temple nearby but far less touristic built in 1993 in memory of the Vietnamese killed at Cu Chi. Return to Saigon. Overnight in Ho Chi Minh.\"},{\"title\":\"Day\",\"day\":7,\"index\":6,\"image\":\"http:\\/\\/res.cloudinary.com\\/multizonetravels-com\\/image\\/upload\\/v1532773659\\/ruytqyv6eynpjrag4ueu.jpg\",\"caption\":\"Ho Chi Minh city \\u2013 Departure (B)\",\"date\":\"19-10-2018 Friday\",\"todo\":\"Free till meet our driver for transfer to airport for your flight home.\"}]', '[{\"id\":0,\"from\":\"Delhi (DEL)\",\"to\":\"Bangkok (BKK)\",\"name\":\"Thai\",\"fno\":\"332\",\"dep_date\":\"13\\/10\\/2018\",\"arv_date\":\"13\\/10\\/2018\",\"dep_time\":\"03:20 AM\",\"arv_time\":\"09:15 AM\"},{\"id\":1,\"from\":\"Bangkok (BKK)\",\"to\":\"Hanoi (HAN)\",\"name\":\"Thai\",\"fno\":\"564\",\"dep_date\":\"13\\/10\\/2018\",\"arv_date\":\"13\\/10\\/2018\",\"dep_time\":\"05:50 PM\",\"arv_time\":\"07:40 PM\"},{\"id\":2,\"from\":\"Ho Chi Minh (SGN)\",\"to\":\"Kuala-lumpur (KUL)\",\"name\":\"AirAsia Airways\",\"fno\":\"527\",\"dep_date\":\"19\\/10\\/2018\",\"arv_date\":\"19\\/10\\/2018\",\"dep_time\":\"01:25 PM\",\"arv_time\":\"04:20 PM\"},{\"id\":3,\"from\":\"Kuala-lumpur (KUL)\",\"to\":\"Delhi (DEL)\",\"name\":\"AirAsia X Airways\",\"fno\":\"182\",\"dep_date\":\"19\\/10\\/2018\",\"arv_date\":\"19\\/10\\/2018\",\"dep_time\":\"07:05 PM\",\"arv_time\":\"10:00 PM\"}]', '[]', '[{\"id\":0,\"check_in\":\"13\\/10\\/2018\",\"city\":\"Hanoi\",\"hotel_name\":\"Hanoi Boutique\",\"room_type\":\"Deluxe Room\",\"rooms\":3,\"nights\":2,\"check_out\":\"15\\/10\\/2018\"},{\"id\":1,\"city\":\"Ha Long bay\",\"hotel_name\":\"V Spirit cruise\",\"room_type\":\"Deluxe Cabin\",\"rooms\":3,\"nights\":2,\"check_out\":\"17\\/10\\/2018\",\"check_in\":\"15\\/10\\/2018\"},{\"id\":2,\"city\":\"Ho Chi Minh City\",\"hotel_name\":\"Elios Hotel\",\"room_type\":\"Senior Sup\",\"rooms\":3,\"nights\":2,\"check_out\":\"19\\/10\\/2018\",\"check_in\":\"17\\/10\\/2018\"}]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quot