(19, 'JHARKHAND (RNC-DEO) || 5N- 6D', NULL, '7781000140', NULL, 'JHARKHAND', '2018-09-02', 5, 0, 2, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":null,\"caption\":\"RANCHI TO DEOGHAR (247 Kms Approx - 06 Hrs)\",\"date\":\"02-09-2018 Sunday\",\"todo\":\"Morning arrival at Ranchi, and you will be met our representative and transferred to Deoghar. Arrive and check-in at the hotel. Enjoy rest of the evening at leisure and a comfortable overnight at the hotel.\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":null,\"caption\":\"DEOGHAR\",\"date\":\"03-09-2018 Monday\",\"todo\":\"After breakfast, visit Baba Baidyanath Temple, Trikuta Hills and Naulakha Mandir. Overnight stay at the hotel.\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":null,\"caption\":\"DEOGHAR\",\"date\":\"04-09-2018 Tuesday\",\"todo\":\"After breakfast, visit Basukinath, Parasnath Hill and Madhuban. Overnight stay at the hotel.\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":null,\"caption\":\"DEOGHAR TO RANCHI   (247 Kms Approx - 06 Hrs)\",\"date\":\"05-09-2018 Wednesday\",\"todo\":\"After breakfast, check out from hotel and proceed to Ranchi. Arrive and check-in at the hotel. After lunch visit Rock Garden, Kanke Dam. Enjoy rest of the evening at leisure and a comfortable overnight at the hotel.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":null,\"caption\":\"RANCHI\",\"date\":\"06-09-2018 Thursday\",\"todo\":\"Early morning, visit Pahari Mandir. After breakfast visit Deori Mandir, Sun Temple and Dassam Falls.Spend a comfortable overnight stay at the hotel.\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":null,\"caption\":\"DEPARTURE FROM RANCHI\",\"date\":\"07-09-2018 Friday\",\"todo\":\"After an early breakfast, check out of the hotel in Ranchi. Visit Patratu Dam. Enjoy local food\\/cuisine at a good restaurant (personal expense). Drive back to Ranchi and drop to Airport or Railway Station.\"}]', '[]', '[]', '[]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quote.</li><li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li><li><strong>5.0% GST will be applicable against final Invoice (Subject to Payment Made in INR).</strong></li><li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li><li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li><li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li><li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li><li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li></ul>', '[]', NULL, NULL, NULL, NULL, '{\"profit_percent\":0,\"package\":{\"flight_cost\":0}}', 'MZQ/016/082018', 0, NULL, 0, '2018-08-09 10:51:22', '2018-08-09 10:51:22', 0, 0, NULL, 0, 0),
(20, 'JHARKHAND (RNC-HAZ) || 4N- 5D', NULL, '7781000140', NULL, 'JHARKHAND', '2018-09-03', 4, 0, 2, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":null,\"caption\":\"RANCHI TO HAZARIBAGH (95 Kms Approx - 03 Hrs)\",\"date\":\"03-09-2018 Monday\",\"todo\":\"Morning arrival at Ranchi, and you will be met our representative and transferred to Hazaribagh. Arrive and check-in at the hotel. Enroute, halt for refreshments and visit Patratu Dam. Arrive and check-in at the hotel. After lunch visit Canary Hills, Suraj Kunj. Spend a comfortable overnight stay at the hotel.\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":null,\"caption\":\"HAZARIBAGH\",\"date\":\"04-09-2018 Tuesday\",\"todo\":\"After breakfast, visit Rajrappa Temple. After lunch, visit Sanskriti Museum, Art Gallery and Megaliths Of Hazaribagh. Overnight stay at the hotel.\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":null,\"caption\":\"HAZARIBAGH TO RANCHI (95 Kms Approx - 03 Hrs)\",\"date\":\"05-09-2018 Wednesday\",\"todo\":\"After breakfast, check out from hotel and proceed to Ranchi. Arrive and check-in at the hotel. After lunch visit Rock Garden,\\nKanke Dam. Enjoy rest of the evening at leisure and a comfortable overnight at the hotel.\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":null,\"caption\":\"RANCHI\",\"date\":\"06-09-2018 Thursday\",\"todo\":\"Early morning, visit Pahari Mandir. After breakfast visit Jonha Falls, Hundru Falls (Optional), Jagannath Temple. In the evening return to the hotel and enjoy  rest of the evening at leisure and a comfortable overnight at the hotel.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":null,\"caption\":\"DEPARTURE FROM RANCHI\",\"date\":\"07-09-2018 Friday\",\"todo\":\"After an early breakfast, check out of the hotel and drop to Airport or Railway Station.\"}]', '[]', '[]', '[]', '<ul><li>This is just a quote, no reservations held yet or booking is not proceed yet.</li><li>The rooms &amp; rates are subject to availability at the time of booking / confirmation.</li><li>Hotel, Sightseeing, Meals, Transfers rate might change without any prior notice until &amp; unless it been booked/ confirmed from your end.</li><li>The change in dates will attract re-quote.</li><li>Normal Hotel check-in time is from 14.00 hrs onwards. &amp; check-out time is at 12.00 hrs.</li><li><strong>5.0% GST will be applicable against final Invoice (Subject to Payment Made in INR).</strong></li><li>Additional Bank charges will be applicable, if payment is made in foreign currency.</li><li>The above cost does not include any kind of surcharge if applicable during the given travel period.</li><li>There will be an additional cost for an entire transfer between 23:00 - 07:00 hrs (if not stated inside the package).</li><li>At check in all guests will be required to present a Major Credit Card for incidentals. \"No Show\" is subject to Full Booking Charges</li><li>Quotation might change due to currencies ROE fluctuation during confirmation &amp; booking process.</li></ul>', '[]', NULL, NULL, NULL, NULL, '{\"profit_percent\":0,\"package\":{\"flight_cost\":0}}', 'MZQ/017/082018', 0, NULL, 0, '2018-08-09 11:38:10', '2018-08-13 08:18:24', 0, 0, NULL, 0, 0),
