(69, 'MS SHYONEE ROY', 'Mr Anup Jyoti', '9830376160', 'shyonee27@gmail.com', 'SINGAPORE', '2019-02-21', 5, 0, 2, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":null,\"caption\":\"AIRPORT TO SINGAPORE HOTEL || CITY TOUR + GARDEN OF THE BAY\",\"date\":\"21-02-2019 Thursday\",\"todo\":\"Upon arrival at Singapore transfer to hotel. After lunch proceed for City Tour of Singapore with Garden By The Bay.\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":null,\"caption\":\"SINGAPORE HOTEL TO SINGAPORE PORT || CRUISING\",\"date\":\"22-02-2019 Friday\",\"todo\":\"Check-out from Hotel & Transfer to Cruise Terminal.TIME- 16:30 || EMBARK\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":null,\"caption\":\"PENANG - MALAYSIA || CRUISING\",\"date\":\"23-02-2019 Saturday\",\"todo\":\"By Cruise  PENANG - MALAYSIA || TIME- 15:00- 23:00 | DOCKED\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":null,\"caption\":\"CRUISE\",\"date\":\"24-02-2019 Sunday\",\"todo\":\"Full Day Cruising.\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":null,\"caption\":\"SINGAPORE PORT ARRIVAL ||  SENTOSA TOUR\",\"date\":\"25-02-2019 Monday\",\"todo\":\"TIME- 08:00 || DEBARK\\nTransfer from Cruise Terminal to Singapore Hotel.\\nSentosa  (cable Car + Wings Of Time 8.40 pm) (Cable Car + Wings Of Time (2nd Show))+- Madame Tussauds + Images Of Singapore Live+- Trick Eye Museum.\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":null,\"caption\":\"SINGAPORE || UNIVERSAL STUDIOS\",\"date\":\"26-02-2019 Tuesday\",\"todo\":\"Check-out from hotel Universal Studios Ticket with Lunch  &  Transfer.\\nAfter Dinner transfer to Airport.\"}]', '[{\"id\":1,\"from\":\"Kolkata (CCU)\",\"to\":\"Singapore (SIN)\",\"name\":\"Singapore Airlines\",\"fno\":\"5487\",\"dep_date\":\"20 Feb 2019\",\"arv_date\":\"21 Feb 2019\",\"dep_time\":\"11:55 PM\",\"arv_time\":\"06:40 AM\",\"fare\":\"54210\"},{\"id\":2,\"from\":\"Singapore (SIN)\",\"to\":\"Kolkata (CCU)\",\"name\":\"Singapore Airlines\",\"fno\":\"5488\",\"d