(205, 'MR MANOJ MITTAL', 'YATRA', '9431102005', 'info@multizonetravels.com', 'SOUTH KERALA', '2021-03-25', 7, 0, 4, '[]', '[{\"id\":1,\"from\":\"Madurai (IXM)\",\"to\":\"Chennai (MAA)\",\"name\":\"IndiGo\",\"fno\":\"7194\",\"dep_date\":\"30 Mar 2021\",\"arv_date\":\"30 Mar 2021\",\"dep_time\":\"08:10 AM\",\"arv_time\":\"09:40 AM\",\"fare\":14460},{\"id\":2,\"from\":\"Chennai (MAA)\",\"to\":\"Hyderabad (HYD)\",\"name\":\"IndiGo\",\"fno\":\"591\",\"dep_date\":\"30 Mar 2021\",\"arv_date\":\"30 Mar 2021\",\"dep_time\":\"11:10 AM\",\"arv_time\":\"12:15 PM\",\"fare\":0},{\"id\":3,\"from\":\"Hyderabad (HYD)\",\"to\":\"Ranchi (IXR)\",\"name\":\"IndiGo\",\"fno\":\"981\",\"dep_date\":\"31 Mar 2021\",\"arv_date\":\"31 Mar 2021\",\"dep_time\":\"04:45 PM\",\"arv_time\":\"06:25 PM\",\"fare\":9232},{\"id\":4,\"from\":\"Hyderabad (HYD)\",\"to\":\"Delhi (DEL)\",\"name\":\"AirIndia\",\"fno\":\"541\",\"dep_date\":\"31 Mar 2021\",\"arv_date\":\"31 Mar 2021\",\"dep_time\":\"04:15 PM\",\"arv_time\":\"06:30 PM\",\"fare\":9232}]', '[]', '[{\"id\":0,\"check_in\":\"25\\/03\\/2021\",\"city\":\"KOVALAM\",\"hotel_name\":\"SAGARA BEACH RESORT\",\"room_type\":\"STANDARD DBL AC\",\"rooms\":2,\"meal\":\"cp\",\"nights\":2,\"check_out\":\"27\\/03\\/2021\",\"rate\":\"8387\"},{\"id\":1,\"check_in\":\"27\\/03\\/2021\",\"city\":\"KANYAKUMARI\",\"hotel_name\":\"HOTEL SEAFACE\",\"room_type\":\"STANDARD DBL AC\",\"rooms\":2,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"28\\/03\\/2021\",\"rate\":\"4728\"},{\"id\":2,\"check_in\":\"28\\/03\\/2021\",\"city\":\"RAMESHWARAM\",\"hotel_name\":\"HOTEL RAMESHWARAM GRAND\",\"room_type\":\"SUPERIOR DBL\",\"rooms\":2,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"29\\/03\\/2021\",\"rate\":\"3692\"},{\"id\":3,\"check_in\":\"29\\/03\\/2021\",\"city\":\"MADURAI\",\"hotel_name\":\"POPPYS HOTEL\",\"room_type\":\"EXECUTIVE KING DBL\",\"rooms\":2,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"30\\/03\\/2021\",\"rate\":\"4793\"},{\"id\":4,\"check_in\":\"30\\/03\\/2021\",\"city\":\"S