INSERT INTO `quotation` (`id`, `guest_name`, `ref_name`, `mobile_no`, `email`, `destination`, `tentative_date`, `nights`, `children`, `adults`, `itineraries`, `flights`, `trains`, `hotels`, `terms_conditions`, `children_ages`, `inclusion`, `exclusion`, `payment_policy`, `cancellation_policy`, `costing`, `ref_id`, `total`, `adult_cost`, `child_cost`, `created_at`, `updated_at`, `is_confirmed`, `hide_note`, `other_details`, `is_feedback_sent`, `is_feedback_received`) VALUES
(374, 'MR JIGAR', 'BNI | CELEB', '9687110148', 'info@multizonetravels.com', 'ANDAMAN', '2023-12-03', 5, NULL, 2, '[{\"title\":\"Sunday\",\"day\":\"Day 1\",\"index\":0,\"image\":null,\"caption\":\"Airport Pickup. Later Carbyns Cove Beach and Light and Sound Show at  Cellular Jail\",\"date\":\"03-12-2023\",\"todo\":\"<ul>\\n\\t<li>Arrive&nbsp;at&nbsp;Port&nbsp;Blair&nbsp;in&nbsp;the&nbsp;morning\\/afternoon&nbsp;by&nbsp;flight&nbsp;and&nbsp;our&nbsp;representative&nbsp;will&nbsp;be&nbsp;waiting&nbsp; outside&nbsp;the&nbsp;airport&nbsp;holding&nbsp;a&nbsp;placard&nbsp;with&nbsp;your&nbsp;name&nbsp;on&nbsp;it.&nbsp;You&nbsp;will&nbsp;be&nbsp;taken&nbsp;to&nbsp;your&nbsp;hotel&nbsp; where&nbsp;you&nbsp;rest&nbsp;and&nbsp;relax.&nbsp;Later&nbsp;we&nbsp;proceed&nbsp;to&nbsp;Corbyn&amp;#39;s&nbsp;Cove.&nbsp;Coastal&nbsp;drive&nbsp;to&nbsp;this&nbsp; beach&nbsp;is&nbsp;awesome,&nbsp;a&nbsp;stretch&nbsp;of&nbsp;around&nbsp;4&nbsp;Km&nbsp;with&nbsp;an&nbsp;open&nbsp;sea&nbsp;towards&nbsp;your&nbsp;left&nbsp;is&nbsp;a&nbsp;sight&nbsp;to&nbsp; experience.&nbsp;&nbsp;<\\/li>\\n<\\/ul>\\n\\n<ul>\\n\\t<li>Take&nbsp;pit&nbsp;stops&nbsp;during&nbsp;this&nbsp;ride&nbsp;to&nbsp;click&nbsp;pictures&nbsp;and&nbsp;to&nbsp;explore&nbsp;the&nbsp;beauty.&nbsp;Later&nbsp;proceed&nbsp;to&nbsp; attend&nbsp;the&nbsp;enthralling&nbsp;Sound&nbsp;and&nbsp;Light&nbsp;Show&nbsp;at&nbsp;Cellular&nbsp;Jail&nbsp;-&nbsp;where&nbsp;the&nbsp;heroic&nbsp;saga&nbsp;of&nbsp;the&nbsp; Indian&nbsp;freedom&nbsp;struggle&nbsp;is&nbsp;brought&nbsp;alive.&nbsp;&nbsp;&nbsp;<\\/li>\\n<\\/ul>\\n\\n<ul>\\n\\t<li>&nbsp;Enacting&nbsp;of&nbsp;freedom&nbsp;fighters&nbsp;and&nbsp;their&nbsp;struggle&nbsp;for&nbsp;India&amp;#39;s&nbsp;Independence&nbsp;is&nbsp;enacted&nbsp; during&nbsp;this&nbsp;trip.&nbsp;Post&nbsp;completion&nbsp;of&nbsp;this&nbsp;trip,&nbsp;we&nbsp;drop&nbsp;you&nbsp;back&nbsp;at&nbsp;your&nbsp;hotel.&nbsp;<\\/li>\\n<\\/ul>\"},{\"title\":\"Monday\",\"day\":\"Day 2\",\"index\":1,\"image\":null,\"caption\":\"Port Blair To Havelock in Cruise. Later Radhanagar Beach visit Until Sunset\",\"date\":\"04-12-2023\",\"todo\":\"<ul>\\n\\t<li>Today&nbsp;we&nbsp;depart&nbsp;to&nbsp;the&nbsp;Andaman&nbsp;Islands&nbsp;most&nbsp;amazing&nbsp;destination,&nbsp;Havelock&nbsp;Island.&nbsp;This&nbsp; destination&nbsp;is&nbsp;rated&nbsp;as&nbsp;the&nbsp;best&nbsp;island&nbsp;in&nbsp;India.&nbsp;Depart&nbsp;from&nbsp;Port&nbsp;Blair&nbsp;to&nbsp;Havelock&nbsp;Island&nbsp;on&nbsp;a&nbsp; ferry.&nbsp;Upon&nbsp;reaching&nbsp;Havelock,&nbsp;our&nbsp;representative&nbsp;attends&nbsp;you&nbsp;and&nbsp;will&nbsp;drop&nbsp;you&nbsp;at&nbsp;your&nbsp; hotel.&nbsp;Later&nbsp;we&nbsp;begin&nbsp;our&nbsp;journey&nbsp;to&nbsp;one&nbsp;of&nbsp;Asia&amp;#39;s&nbsp;best&nbsp;beaches,&nbsp;Radhanagar&nbsp;Beach.&nbsp;&nbsp;<\\/li>\\n<\\/ul>\\n\\n<ul>\\n\\t<li>Explore&nbsp;this&nbsp;white&nbsp;sand&nbsp;beach&nbsp;and&nbsp;bask&nbsp;in&nbsp;the&nbsp;beauty&nbsp;of&nbsp;this&nbsp;natural&nbsp;wonder.&nbsp;You&nbsp;stay&nbsp;at&nbsp;this&nbsp; beach&nbsp;until&nbsp;sunset.&nbsp;Post&nbsp;this&nbsp;we&nbsp;drop&nbsp;you&nbsp;back&nbsp;to&nbsp;your&nbsp;resort&nbsp;where&nbsp;you&nbsp;relax&nbsp;and&nbsp;unwind.<\\/li>\\n<\\/ul>\"},{\"title\":\"Tuesday\",\"day\":\"Day 3\",\"index\":2,\"image\":null,\"caption\":\"Elephant Beach Boat Ride Tour and Complimentary Snorkelling with Hotel  Pickup and Drop\",\"date\":\"05-12-2023\",\"todo\":\"<ul>\\n\\t<li>Well,&nbsp;how&nbsp;about&nbsp;exploring&nbsp;something&nbsp;underwater.&nbsp;Today,&nbsp;we&nbsp;begin&nbsp;our&nbsp;journey&nbsp;to&nbsp;the&nbsp;most&nbsp; visited&nbsp;snorkeling&nbsp;destination&nbsp;in&nbsp;Havelock&nbsp;Island,&nbsp;Elephant&nbsp;Beach.&nbsp;Around&nbsp;30&nbsp;Minutes&nbsp;by&nbsp; boat,&nbsp;Elephant&nbsp;Beach&nbsp;flaunts&nbsp;one&nbsp;of&nbsp;the&nbsp;best&nbsp;reefs&nbsp;in&nbsp;Havelock&nbsp;Island.&nbsp;<\\/li>\\n\\t<li>\\n\\t<p>The&nbsp;great&nbsp;thing&nbsp;is&nbsp;that&nbsp;the&nbsp;reef&nbsp;here&nbsp;starts&nbsp;at&nbsp;a&nbsp;depth&nbsp;of&nbsp;less&nbsp;than&nbsp;a&nbsp;meter.&nbsp;Upon&nbsp;reaching&nbsp;Elephant&nbsp; Beach,&nbsp;we&nbsp;rest&nbsp;and&nbsp;relax.&nbsp;&nbsp;<\\/p>\\n\\t<\\/li>\\n\\t<li>\\n\\t<p>Later,&nbsp;a&nbsp;guide&nbsp;takes&nbsp;you&nbsp;to&nbsp;provide&nbsp;a&nbsp;complimentary&nbsp;snorkeling&nbsp;session&nbsp;at&nbsp;Elephant&nbsp;Beach&nbsp;(Snorkeling&nbsp;at&nbsp;Havelock&nbsp;Island&nbsp;depends&nbsp;upon&nbsp;the&nbsp;association&nbsp;guidelines).&nbsp;After&nbsp;the&nbsp;trip,&nbsp;we&nbsp;return&nbsp;back&nbsp;from&nbsp;Elephant&nbsp;beach&nbsp;to&nbsp;the&nbsp;Havelock&nbsp;dock&nbsp;in&nbsp;a&nbsp;boat.&nbsp;At&nbsp;the&nbsp;dock,&nbsp;our&nbsp;team&nbsp;attends&nbsp;you&nbsp;and&nbsp;drops&nbsp;you&nbsp;at&nbsp;your&nbsp;hhotel.&nbsp;<\\/p>\\n\\t<\\/li>\\n\\t<li>\\n\\t<p>Note:&nbsp;Our&nbsp;team&nbsp;at&nbsp;Havelock&nbsp;will&nbsp;guide&nbsp;you&nbsp;in&nbsp;case&nbsp;you&nbsp;require&nbsp;any&nbsp;assistance&nbsp;on&nbsp;the&nbsp;ground .<\\/p>\\n\\t<\\/li>\\n<\\/ul>\"},{\"title\":\"Wednesday\",\"day\":\"Day 4\",\"index\":3,\"image\":null,\"caption\":\"Havelock To Neil Island in Cruise. Later Visit Laxmanpur Beach For Sunset\",\"date\":\"06-12-2023\",\"todo\":\"<ul>\\n\\t<li>Check&nbsp;out&nbsp;from&nbsp;the&nbsp;hotel&nbsp;in&nbsp;Havelock&nbsp;Island&nbsp;and&nbsp;board&nbsp;a&nbsp;premium&nbsp;cruise&nbsp;to&nbsp;Neil&nbsp;Island,&nbsp;upon reaching&nbsp;Neil&nbsp;Island&nbsp;our&nbsp;representative&nbsp;will&nbsp;assist&nbsp;you&nbsp;to&nbsp;your&nbsp;resort&nbsp;to&nbsp;check-in.&nbsp;Rest&nbsp;at&nbsp;the hotel&nbsp;and&nbsp;then&nbsp;proceed&nbsp;to&nbsp;visit&nbsp;Laxmanpur&nbsp;beach.&nbsp;This&nbsp;is&nbsp;a&nbsp;secluded&nbsp;beach&nbsp;that&nbsp;lies&nbsp;2&nbsp;km&nbsp; north&nbsp;of&nbsp;Neil&amp;#39;s&nbsp;jetty.&nbsp;Experience&nbsp;a&nbsp;magnificent&nbsp;sunset&nbsp;at&nbsp;this&nbsp;beach.&nbsp;Post&nbsp;this&nbsp;we&nbsp;drop&nbsp; you&nbsp;back&nbsp;to&nbsp;your&nbsp;hotel&nbsp;in&nbsp;Neil&nbsp;Island.&nbsp;<\\/li>\\n\\t<li>\\n\\t<p>&nbsp;Ferry&nbsp;Timing&nbsp;from&nbsp;Havelock&nbsp;to&nbsp;Neil&nbsp;Island&nbsp;is&nbsp;around&nbsp;10:00&nbsp;AM.&nbsp;Ferry&nbsp;timings&nbsp;are&nbsp;subject&nbsp;tochange&nbsp; and&nbsp;our&nbsp;team&nbsp;will&nbsp;update&nbsp;you&nbsp;in&nbsp;case&nbsp;of&nbsp;such&nbsp;changes.&nbsp;<\\/p>\\n\\t<\\/li>\\n<\\/ul>\"},{\"title\":\"Thursday\",\"day\":\"Day 5\",\"index\":4,\"image\":null,\"caption\":\"Natural Rock Formation and Bharatpur Beach Trip. Later Neil to Port Blair in  Cruise and Hotel Drop + Shopping trip\",\"date\":\"07-12-2023\",\"todo\":\"<ul>\\n\\t<li>Today,&nbsp;we&nbsp;begin&nbsp;our&nbsp;journey&nbsp;to&nbsp;visit&nbsp;Natural&nbsp;rock&nbsp;formation&nbsp;which&nbsp;is&nbsp;a&nbsp;major&nbsp;attraction&nbsp;at&nbsp;Neil.&nbsp; Post&nbsp;this&nbsp;we&nbsp;visit&nbsp;Bharatpur&nbsp;Beach&nbsp;where&nbsp;you&nbsp;can&nbsp;indulge&nbsp;yourself&nbsp;in&nbsp;swimming&nbsp;and&nbsp;water&nbsp; activities&nbsp;such&nbsp;as&nbsp;Scuba&nbsp;Diving,&nbsp;Glass&nbsp;bottom&nbsp;boat&nbsp;ride&nbsp;and&nbsp;Jet&nbsp;Ski&nbsp;ride.&nbsp;Food&nbsp;options&nbsp;are&nbsp; available&nbsp;at&nbsp;Bharatpur&nbsp;beach.&nbsp;<\\/li>\\n\\t<li>\\n\\t<p>Post&nbsp;completion&nbsp;of&nbsp;the&nbsp;trip&nbsp;we&nbsp;drop&nbsp;you&nbsp;back&nbsp;to&nbsp;Neil&nbsp;jetty&nbsp;to&nbsp;board&nbsp;a&nbsp;cruise&nbsp;to&nbsp;Port&nbsp;Blair.&nbsp;Upon&nbsp;reaching&nbsp; Port&nbsp;Blair&nbsp;our&nbsp;representative&nbsp;will&nbsp;attend&nbsp;you&nbsp;and&nbsp;will&nbsp;drop&nbsp;you&nbsp;to&nbsp;the&nbsp;hotel&nbsp;for&nbsp; overnight&nbsp;stay.<\\/p>\\n\\t<\\/li>\\n<\\/ul>\"},{\"title\":\"Friday\",\"day\":\"Day 6\",\"index\":5,\"image\":null,\"caption\":\"Drop to the Airport\",\"date\":\"08-12-2023\",\"todo\":\"<ul>\\n\\t<li>Check&nbsp;out&nbsp;from&nbsp;the&nbsp;hotel&nbsp;and&nbsp;proceed&nbsp;to&nbsp;the&nbsp;airport&nbsp;to&nbsp;return&nbsp;home&nbsp;with&nbsp;sweet&nbsp;memories&nbsp;of&nbsp; this&nbsp;exotic&nbsp;destination.&nbsp;<\\/li>\\n\\t<li>\\n\\t<p>Do&nbsp;note&nbsp;that&nbsp;hotels&nbsp;have&nbsp;an&nbsp;early&nbsp;check-out&nbsp;time.&nbsp;Guest&nbsp;will&nbsp;need&nbsp;to&nbsp;keep&nbsp;their&nbsp;luggage&nbsp;in&nbsp;the&nbsp; reception&nbsp;kiosk&nbsp;if&nbsp;your&nbsp;scheduled&nbsp;flight&nbsp;is&nbsp;in&nbsp;the&nbsp;afternoon.&nbsp;If&nbsp;you&nbsp;wish&nbsp;to&nbsp;visit&nbsp;any&nbsp;attraction&nbsp; during&nbsp;your&nbsp;free&nbsp;time&nbsp;then&nbsp;do&nbsp;let&nbsp;us&nbsp;know.&nbsp;<\\/p>\\n\\t<\\/li>\\n<\\/ul>\"}]', '[{\"id\":1,\"from\":\"Kolkata (CCU)\",\"to\":\"Portblair (IXZ)\",\"name\":\"SpiceJet\",\"fno\":\"871\",\"dep_date\":\"03 Dec 2023\",\"arv_date\":\"03 Dec 2023\",\"dep_time\":\"11:45 AM\",\"arv_time\":\"02:00 PM\",\"fare\":27432},{\"id\":2,\"from\":\"Portblair (IXZ)\",\"to\":\"Kolkata (CCU)\",\"name\":\"IndiGo\",\"fno\":\"6396\",\"dep_date\":\"08 Dec 2023\",\"arv_date\":\"08 Dec 2023\",\"dep_time\":\"12:00 PM\",\"arv_time\":\"01:55 PM\",\"fare\":19286}]', '[]', '[{\"id\":0,\"check_in\":\"03\\/12\\/2023\",\"city\":\"PORTBLAIR\",\"hotel_name\":\"Hotel TSG Emerald\",\"room_type\":\"Cozy Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"04\\/12\\/2023\",\"rate\":null},{\"id\":2,\"check_in\":\"04\\/12\\/2023\",\"city\":\"HAVELOCK\",\"hotel_name\":\"Hotel Havelock Island  Beach Resort\",\"room_type\":\"Deluxe Cottage\",\"rate\":null,\"rooms\":1,\"meal\":\"cp\",\"nights\":2,\"check_out\":\"06\\/12\\/2023\"},{\"id\":3,\"check_in\":\"06\\/12\\/2023\",\"city\":\"NEIL ISLAND\",\"hotel_name\":\"Hotel Tango Beach  Resort\",\"room_type\":\"Tango Premium Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"07\\/12\\/2023\",\"rate\":null},{\"id\":3,\"check_in\":\"07\\/12\\/2023\",\"city\":\"PORTBLAIR\",\"hotel_name\":\"Hotel TSG Emerald\",\"room_type\":\"Cozy Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"08\\/12\\/2023\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are subject to availability at the time of confirmation.</li>\n	<li>In case of unavailability in the listed hotels, arrangement for an alternate accommodation will be made in a hotel of similar standard.</li>\n	<li>There will be no refund for unused nights or early check-out (In case of Medical condition it completely depends on hotel policy).</li>\n	<li>Check-in and check-out times at hotels would be as per hotel policies. Early check-in or late check-out is subject to availability and may be chargeable by the hotel.</li>\n	<li>The price does not include expenses of personal nature, such as laundry, telephone calls, room service, alcoholic beverages, mini bar charges, tips, portage, camera fees etc.</li>\n	<li>Multi Zone Travels reserves the right to modify the itinerary at any point, due to reasons including but not limited to: Force Majeure events, strikes, fairs, festivals, weather conditions, traffic problems, overbooking of hotels / flights, cancellation / re-routing of flights, closure of / entry restrictions at a place of visit, etc. While we will do our best to make suitable alternate arrangements, we would not be held liable for any refunds/compensation claims arising out of this.</li>\n	<li>In case a flight gets cancelled, Multi Zone Travels will not be liable to provide any alternate flights within the same cost, any additional cost incurred for the same shall be borne by the traveller.</li>\n	<li>For more details click <a href=\"https://res.cloudinary.com/anilsam90/image/upload/v1534070888/terms.pdf\" target=\"_blank\">here</a></li>\n</ul>', '[]', '<ul>\n	<li>Return Train/AirFare Ex-Kolkata.</li>\n	<li>Accommodation&nbsp;in&nbsp;rooms&nbsp;as&nbsp;given&nbsp;at&nbsp;hotels&nbsp;in&nbsp;Port&nbsp;Blair,&nbsp;Havelock&nbsp;and&nbsp;Neil&nbsp;with&nbsp;breakfast and&nbsp;all&nbsp;taxes&nbsp;on&nbsp;1&nbsp;Double&nbsp;sharing&nbsp;basis.&nbsp;&nbsp;</li>\n	<li>Meet&nbsp;and&nbsp;greet&nbsp;service&nbsp;at&nbsp;airport.&nbsp;&nbsp;</li>\n	<li>All&nbsp;sightseeing&nbsp;by&nbsp;1&nbsp;Private&nbsp;AC&nbsp;Vehicle&nbsp;at&nbsp;all&nbsp;the&nbsp;islands.&nbsp;&nbsp;</li>\n	<li>Transfer&nbsp;to&nbsp;Havelock&nbsp;Island/Neil&nbsp;Island&nbsp;in&nbsp;Nautika/Makruzz/Green&nbsp;Ocean&nbsp;&nbsp;</li>\n	<li>Full&nbsp;day&nbsp;tour&nbsp;with&nbsp;all&nbsp;transfers&nbsp;including&nbsp;airport&nbsp;pick&nbsp;up&nbsp;and&nbsp;drop.&nbsp;&nbsp;</li>\n	<li>All&nbsp;entry&nbsp;tickets,&nbsp;ferry&nbsp;tickets&nbsp;and&nbsp;permit&nbsp;charges.&nbsp;&nbsp;</li>\n	<li>Personal&nbsp;Tour&nbsp;Coordinators&nbsp;for&nbsp;one&nbsp;Point&nbsp;of&nbsp;Contact.&nbsp;&nbsp;</li>\n	<li>Travel&nbsp;assistance&nbsp;by&nbsp;field&nbsp;executive&nbsp;at&nbsp;all&nbsp;the&nbsp;major&nbsp;entry&nbsp;exit&nbsp;points&nbsp;(Airport/Jetty/Jail/Water&nbsp; sports&nbsp;complex,&nbsp;Havelock&nbsp;/&nbsp;Neil&nbsp;etc).&nbsp;&nbsp;</li>\n	<li>All&nbsp;dedicated&nbsp;vehicle&nbsp;charges&nbsp;(Scorpio,&nbsp;Xylo&nbsp;,&nbsp;Ertiga&nbsp;,&nbsp;Tavera,&nbsp;Swift&nbsp;Desire&nbsp;)&nbsp;as&nbsp;per&nbsp;itinerary in&nbsp;AC&nbsp;and&nbsp;not&nbsp;at&nbsp;disposal.&nbsp;&nbsp;</li>\n	<li>GST&nbsp;is&nbsp;included&nbsp;in&nbsp;this&nbsp;package.</li>\n</ul>', '<ul>\n	<li>Any kind of personal expenses.</li>\n	<li>Tips, Insurance, Laundry, Phone Calls, Guide Fee &amp; Camera Fee.</li>\n	<li>Anything not mentioned in the inclusions above.</li>\n</ul>', NULL, NULL, '{\"profit_percent\":\"24\",\"package\":{\"flight_cost\":46718,\"hotel_cost\":null,\"land_cost\":\"49627\"},\"extra\":[],\"cost_price\":96345,\"amount_of_percent\":\"Rs 23122.8\",\"selling_price\":119467.800000000002910383045673370361328125}', 'MZQ/0369/072023', 119600, 59800, NULL, '2023-07-04 13:39:35', '2023-07-05 05:08:33', 0, 1, NULL, 0, 0),
(375, 'MR SUBHAM SHINGHANIA', 'BNI | CELEB', '8340771301', 'admin@multizonetravels.com', 'DUBAI', '2023-11-16', 6, 1, 5, '[]', '[{\"id\":1,\"from\":\"Delhi (DEL)\",\"to\":\"Dubai (DXB)\",\"name\":\"IndiGo\",\"fno\":\"23\",\"dep_date\":\"16 Nov 2023\",\"arv_date\":\"16 Nov 2023\",\"dep_time\":\"08:30 AM\",\"arv_time\":\"11:15 AM\",\"fare\":124566},{\"id\":2,\"from\":\"Dubai (DXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"24\",\"dep_date\":\"22 Nov 2023\",\"arv_date\":\"23 Nov 2023\",\"dep_time\":\"08:50 PM\",\"arv_time\":\"01:40 AM\",\"fare\":79866}]', '[]', '[{\"id\":0,\"check_in\":\"16\\/11\\/2023\",\"city\":\"DUBAI\",\"hotel_name\":\"Hotel The Canvas Dubai - MGallery\",\"room_type\":\"Superior Room\",\"rooms\":2,\"meal\":\"cp\",\"nights\":6,\"check_out\":\"22\\/11\\/2023\",\"rate\":\"161508\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are subject to availability at the time of confirmation.</li>\n	<li>In case of unavailability in the listed hotels, arrangement for an alternate accommodation will be made in a hotel of similar standard.</li>\n	<li>There will be no refund for unused nights or early check-out (In case of Medical condition it completely depends on hotel policy).</li>\n	<li>Check-in and check-out times at hotels would be as per hotel policies. Early check-in or late check-out is subject to availability and may be chargeable by the hotel.</li>\n	<li>The price does not include expenses of personal nature, such as laundry, telephone calls, room service, alcoholic beverages, mini bar charges, tips, portage, camera fees etc.</li>\n	<li>Multi Zone Travels reserves the right to modify the itinerary at any point, due to reasons including but not limited to: Force Majeure events, strikes, fairs, festivals, weather conditions, traffic problems, overbooking of hotels / flights, cancellation / re-routing of flights, closure of / entry restrictions at a place of visit, etc. While we will do our best to make suitable alternate arrangements, we would not be held liable for any refunds/compensation claims arising out of this.</li>\n	<li>In case a flight gets cancelled, Multi Zone Travels will not be liable to provide any alternate flights within the same cost, any additional cost incurred for the same shall be borne by the traveller.</li>\n	<li>For more details click <a href=\"https://res.cloudinary.com/anilsam90/image/upload/v1534070888/terms.pdf\" target=\"_blank\">here</a></li>\n</ul>', '[{\"age\":3}]', '<ul>\n	<li>Return Airfare <strong>Ex-Delhi.</strong></li>\n	<li><strong>06 Nights</strong> Accommodation in<strong> Hotel&nbsp;The Canvas Dubai - MGallery.</strong></li>\n	<li><strong>Daily Breakfast </strong>at the Hotel.</li>\n	<li><strong>Dubai Airport transfers</strong> on PVT.</li>\n	<li><strong>Half-Day Dubai City Tour</strong> with&nbsp;<strong>Dubai Mall</strong>&nbsp;&amp;<strong> Fountain Show </strong>on SIC.</li>\n	<li><strong>Burj Khalifa 124th&nbsp;Floor</strong> on SIC.</li>\n	<li><strong>Marina Dhow Cruise </strong>on SIC.</li>\n	<li><strong>Desert Safari </strong>with BBQ Dinner, Belly Dance Show, Tanoura Show, and other camp activities on SIC.&nbsp;</li>\n	<li><strong>Abu Dhabi with Ferrari World Theme Park</strong> with a visit to <strong>Grand Mosque</strong> on PVT.</li>\n	<li><b>Warner Brothers</b> on PVT.</li>\n	<li><b>Museum of the Future&nbsp;</b>on PVT.</li>\n	<li><strong>Dubai Tourist Visa </strong>+ Basic Insurance.</li>\n</ul>', '<ul>\n	<li>Any kind of personal expenses.</li>\n	<li>Tips, Insurance, Laundry, Phone Calls, Guide Fee &amp; Camera Fee.</li>\n	<li>Anything not mentioned in the inclusions above.</li>\n</ul>', NULL, NULL, '{\"profit_percent\":\"11\",\"package\":{\"flight_cost\":204432,\"hotel_cost\":161508,\"land_cost\":\"176205\",\"visa_cost\":\"32000\"},\"extra\":[],\"cost_price\":574145,\"amount_of_percent\":\"Rs 63155.95\",\"selling_price\":637300.94999999995343387126922607421875,\"profit_figure\":null,\"percent_of_amount\":\"13.00%\"}', 'MZQ/0370/072023', 637500, 120600, 34500, '2023-07-14 13:32:11', '2023-07-15 07:59:08', 0, 1, NULL, 0, 0),
(376, 'MR ROHIT KASHYAP', 'ANYTIME FITNESS', '9334616382', 'admin@multizonetravels.com', 'FRANCE', '2023-08-16', 3, 0, 2, '[]', '[{\"id\":1,\"from\":\"Kolkata (CCU)\",\"to\":\"Doha (DOH)\",\"name\":\"Qatar Airways\",\"fno\":\"541\",\"dep_date\":\"16 Aug 2023\",\"arv_date\":\"16 Aug 2023\",\"dep_time\":\"03:50 AM\",\"arv_time\":\"06:25 AM\",\"fare\":\"232384\"},{\"id\":2,\"from\":\"Doha (DOH)\",\"to\":\"Paris (CDG)\",\"name\":\"Qatar Airways\",\"fno\":\"39\",\"dep_date\":\"16 Aug 2023\",\"arv_date\":\"16 Aug 2023\",\"dep_time\":\"08:00 AM\",\"arv_time\":\"01:55 PM\",\"fare\":0},{\"id\":3,\"from\":\"Paris (CDG)\",\"to\":\"Doha (DOH)\",\"name\":\"Qatar Airways\",\"fno\":\"42\",\"dep_date\":\"19 Aug 2023\",\"arv_date\":\"19 Aug 2023\",\"dep_time\":\"09:05 AM\",\"arv_time\":\"04:35 PM\",\"fare\":0},{\"id\":4,\"from\":\"Doha (DOH)\",\"to\":\"Kolkata (CCU)\",\"name\":\"Qatar Airways\",\"fno\":\"540\",\"dep_date\":\"19 Aug 2023\",\"arv_date\":\"20 Aug 2023\",\"dep_time\":\"06:50 PM\",\"arv_time\":\"02:20 AM\",\"fare\":0}]', '[]', '[{\"id\":0,\"check_in\":\"16\\/08\\/2023\",\"city\":\"PARIS\",\"room_type\":\"Urban Room\",\"rate\":\"53819\",\"hotel_name\":\"Hotel Le Meridien Etoile\",\"rooms\":1,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"19\\/08\\/2023\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are subject to availability at the time of confirmation.</li>\n	<li>In case of unavailability in the listed hotels, arrangement for an alternate accommodation will be made in a hotel of similar standard.</li>\n	<li>There will be no refund for unused nights or early check-out (In case of Medical condition it completely depends on hotel policy).</li>\n	<li>Check-in and check-out times at hotels would be as per hotel policies. Early check-in or late check-out is subject to availability and may be chargeable by the hotel.</li>\n	<li>The price does not include expenses of personal nature, such as laundry, telephone calls, room service, alcoholic beverages, mini bar charges, tips, portage, camera fees etc.</li>\n	<li>Multi Zone Travels reserves the right to modify the itinerary at any point, due to reasons including but not limited to: Force Majeure events, strikes, fairs, festivals, weather conditions, traffic problems, overbooking of hotels / flights, cancellation / re-routing of flights, closure of / entry restrictions at a place of visit, etc. While we will do our best to make suitable alternate arrangements, we would not be held liable for any refunds/compensation claims arising out of this.</li>\n	<li>In case a flight gets cancelled, Multi Zone Travels will not be liable to provide any alternate flights within the same cost, any additional cost incurred for the same shall be borne by the traveller.</li>\n	<li>For more details click <a href=\"https://res.cloudinary.com/anilsam90/image/upload/v1534070888/terms.pdf\" target=\"_blank\">here</a></li>\n</ul>', '[]', '<ul>\n	<li>Return Airfare <strong>Ex-Kolkata.</strong></li>\n	<li><strong>03&nbsp;Nights</strong> Accommodation in Well appointed Air-Conditioned Room.</li>\n	<li>Two bottles of mineral water every day.</li>\n	<li>Complimentary use of Tea/Coffee maker. (replenished once daily).</li>\n	<li>Buffet/Fixed Menu <strong>Breakfast</strong>.</li>\n	<li>France Visa Charges.</li>\n</ul>', '<ul>\n	<li>Any kind of personal expenses.</li>\n	<li>Tips, Insurance, Laundry, Phone Calls, Guide Fee &amp; Camera Fee.</li>\n	<li>Anything not mentioned in the inclusions above.</li>\n</ul>', NULL, NULL, '{\"profit_percent\":\"16\",\"package\":{\"flight_cost\":232384,\"hotel_cost\":53819,\"visa_cost\":\"7000\",\"travel_insurance\":\"1040\"},\"extra\":[],\"cost_price\":294243,\"amount_of_percent\":\"Rs 47078.88\",\"selling_price\":341321.880000000004656612873077392578125}', 'MZQ/0371/072023', 341104, 170552, 0, '2023-07-15 06:23:15', '2023-07-20 14:37:18', 0, 1, '\"<p align=\\\"center\\\" style=\\\"text-indent:0px; -webkit-text-stroke-width:0px; text-align:center\\\"><span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><b><span style=\\\"font-size:17.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">TOURIST Visa Requirements for FRANCE (DELHI)<\\/span><\\/span><\\/span><\\/b><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/p>\\n\\n<p align=\\\"center\\\" style=\\\"text-indent:0px; -webkit-text-stroke-width:0px; text-align:center; margin-bottom:10px; margin-left:48px\\\"><span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">(APPLIED THROUGH VFS)&nbsp;<b>KINDLY PROVIDE ALL THE DOCUMENTS IN A4 SIZE. PLEASE DO NOT STAPLE ANY DOCUMENTS<br \\/>\\nKindly check vfs\\/embassy website for the latest visa requirements and quarantine rules, as they change frequently without any intimation.<\\/b><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/p>\\n\\n<ul style=\\\"color:#000000; font-family:Arial, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif; font-size:14px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:start; text-indent:0px; text-transform:none; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; white-space:normal; background-color:#ffffff; text-decoration-thickness:initial; text-decoration-style:initial; text-decoration-color:initial\\\">\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify; margin-bottom:10px\\\"><b><span style=\\\"font-size:12pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Valid passport&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:12pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">must not be older than 10 years also it must be valid for at least THREE MONTHS longer than the intended stay. The passport must also have at least TWO BLANK PAGES to affix the visa and should be along with all old passport booklets. Handwritten passports, Passports with observation, and passports of 20-year validity are NOT acceptable<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\">&nbsp;<\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">1 Visa Form&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">to be filled&nbsp;<b>ONLINE WITH BAR CODE PAGE<\\/b>&nbsp;at&nbsp;<a href=\\\"https:\\/\\/france-visas.gouv.fr\\/\\\" style=\\\"color:#0563c1; text-decoration:underline\\\" target=\\\"_blank\\\">https:\\/\\/france-visas.gouv.fr\\/<\\/a>&nbsp;(<b>Manual Forms NOT accepted at all<\\/b>). This form needs to be&nbsp;<b>printed and signed&nbsp;<\\/b>by the applicant at the appropriate places(along with the Barcode pages -&nbsp;<b>PLEASE SEND FULL PRINT OF THE FORM<\\/b>).<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b>Receipt of Visa Application ( a two pager document with barcode) needs to be printed and given along with the visa application.<\\/b><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Applicant mobile number and Email id.<\\/span><\\/span><\\/b><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">2 Recent Coloured&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Photograph (Fresh ones i.e. NOT used earlier for any visa) should be: -<\\/span><\\/span>\\n\\t<ul>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">35mm x 45mm&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">in dimension<\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">On&nbsp;<b>matte finish&nbsp;<\\/b>paper<\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">With&nbsp;<b>White background<\\/b><\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">With&nbsp;<b>80%&nbsp;<\\/b>face coverage, non-smiling [without sunglasses, specs, a hat\\/cap or other head covering, unless the applicant wears such items because of their religious belief or ethnic background<\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">not previously used in a visa<\\/span><\\/span><\\/b><\\/li>\\n\\t<\\/ul>\\n\\t<\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Photocopy of valid<b>&nbsp;USA, UK and Previous Schengen Visa<\\/b><\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Personal Cover letter&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">to&nbsp;<b>The Visa Officer, Embassy of France&nbsp;<\\/b>with mentioning duration of visit, purpose of visit, expenses clause .Details of all Applicants with name, passport number, If Applicable<\\/span><\\/span>\\n\\t<ul>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Personal Covering Letters&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">should have an instruction to dispatch the passports to the below mentioned address after visa approval.<\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Please courier my passport&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">to the following address:- Pax Name: __________ Address: 30\\/28, 3rd Floor, (Opp. Mughal Mahal Restaurant) East Patel Nagar, New Delhi -110008<\\/span><\\/span><\\/li>\\n\\t<\\/ul>\\n\\t<\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Travel Insurance&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">as per Schengen specification, matching with ticket dates with risk coverage of Euro 30,000. For downloading the list of Approved Insurance Companies and detailed information on Travel Insurance please visit our visa forms section of our website.<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Tour itinerary \\/Day to day Itinerary<\\/span><\\/span><\\/b><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Confirmed Return Ticket (or ticket with Live PNR)&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">covering all the sectors<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Confirmed Hotel<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">&nbsp;as per the ticket (with hotel Name, Address, Telephone no and Email. Id)<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Original 3 months updated Personal bank statement.<\\/span><\\/span><\\/b><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Personal Income Tax Return<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">&nbsp;for the Last 3 years.<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Occupation proof<\\/span><\\/span><\\/b>\\n\\t<ul>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">In case of Employee&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">-Proof of employment(employment certificate\\/NOC)and Pay slip of last 3 months.<\\/span><\\/span><\\/li>\\n\\t\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">In case the applicant is the proprietor\\/owner of the company<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">-, a Cover letter on the company`s letterhead, the company`s Original 3-month bank statement (with bank seal and signature), proof of paid income tax (for 3 years), company memo, partnership deed, establishment license or proprietorship, etc are required.<\\/span><\\/span><\\/li>\\n\\t<\\/ul>\\n\\t<\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">If the minor is accompanied by one parent\\/traveling alone shall provide a&nbsp;<b>NOTARIZED NOC<\\/b>&nbsp;from the other\\/both parents with their passport copy.<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">BIOMETRIC MANDATORY&nbsp;<\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">for all Applicants<\\/span><\\/span><\\/li>\\n\\t<li style=\\\"font-size:11pt; font-family:Calibri, sans-serif; color:black; text-align:justify\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\">Copy of final Covid vaccination certificate.<\\/span><\\/span><\\/li>\\n<\\/ul>\\n\\n<div align=\\\"center\\\" style=\\\"text-indent:0px; -webkit-text-stroke-width:0px; text-align:center\\\">\\n<hr align=\\\"center\\\" width=\\\"100%\\\" \\/><\\/div>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px\\\"><span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><b><span style=\\\"font-size:11.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">Note<\\/span><\\/span><\\/span><\\/b><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/p>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px; margin-left:48px\\\"><br \\/>\\n<span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\"><b>NOTE<\\/b>:&nbsp;<br \\/>\\n1. The Embassy reserves the right to ask for additional documents and\\/or for a personal interview.&nbsp;<br \\/>\\n<br \\/>\\n2. All Schengen Embassies have stopped accepting passports that are handwritten or have any observation on the front data page Hence, all such passport holders are requested to get a fresh passport booklet to apply for Visa&nbsp;<br \\/>\\n3.&nbsp;<b>Photo Appearance<\\/b>: The photograph must be a full-face front view in which the visa applicant is facing the camera directly.<br \\/>\\nThe face should cover about 70-80 percent of the photo area.<br \\/>\\nThe photograph MUST be in color and have only a white background. Photos with dark busy or patterned backgrounds will not be accepted<br \\/>\\nIn general, the applicant\'s head including both face and hair should be shown from the crown of the head to the tip of the chin on top and bottom and from the hairline side-to-side. It is preferable that ears be exposed.<br \\/>\\nSunglasses or other wear which detracts from the face are not acceptable unless required for medical reasons an eye patch, for example.<br \\/>\\nA photograph depicting a person wearing a traditional facemask or veil that does not permit adequate identification is not acceptable.&nbsp;<\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><br \\/>\\n&nbsp;<\\/p>\\n\\n<div align=\\\"center\\\" style=\\\"text-indent:0px; -webkit-text-stroke-width:0px; text-align:center\\\">\\n<hr align=\\\"center\\\" width=\\\"100%\\\" \\/><\\/div>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px\\\"><span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><b><span style=\\\"font-size:11.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">Medical Requirement<\\/span><\\/span><\\/span><\\/b><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/p>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px; margin-left:48px\\\"><span style=\\\"font-size:11pt\\\"><span style=\\\"font-family:Calibri, sans-serif\\\"><span style=\\\"color:#000000\\\"><span style=\\\"font-style:normal\\\"><span style=\\\"font-variant-ligatures:normal\\\"><span style=\\\"font-variant-caps:normal\\\"><span style=\\\"font-weight:400\\\"><span style=\\\"letter-spacing:normal\\\"><span style=\\\"orphans:2\\\"><span style=\\\"text-transform:none\\\"><span style=\\\"widows:2\\\"><span style=\\\"word-spacing:0px\\\"><span style=\\\"white-space:normal\\\"><span style=\\\"background-color:#ffffff\\\"><span style=\\\"text-decoration-thickness:initial\\\"><span style=\\\"text-decoration-style:initial\\\"><span style=\\\"text-decoration-color:initial\\\"><b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">Travel Insurance&nbsp;<\\/span><\\/span><\\/span><\\/b><span style=\\\"font-size:10.5pt\\\"><span style=\\\"font-family:Arial, sans-serif\\\"><span style=\\\"color:black\\\">as per Schengen specification, matching with ticket dates with risk coverage of&nbsp;<b>Euro 30,000.<\\/b>&nbsp;For downloading the list of Approved Insurance Companies and detailed information on Travel Insurance please visit our visa forms section of our website.<\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/span><\\/p>\\n\\n<div align=\\\"center\\\" style=\\\"text-indent:0px; -webkit-text-stroke-width:0px; text-align:center\\\">\\n<hr align=\\\"center\\\" width=\\\"100%\\\" \\/><\\/div>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px\\\">&nbsp;<\\/p>\\n\\n<p style=\\\"text-align:start; text-indent:0px; -webkit-text-stroke-width:0px; margin-bottom:10px\\\">&nbsp;<\\/p>\"', 0, 0),
(377, 'Mrs AISHA AGARWAL', 'BNI EXPLORERS', '9905528848', 'admin@multizonetravels.com', 'DUBAI', '2023-09-08', 8, 0, 3, '[]', '[{\"id\":1,\"from\":\"Ranchi (IXR)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"2094\",\"dep_date\":\"07 Sep 2023\",\"arv_date\":\"07 Sep 2023\",\"dep_time\":\"04:15 PM\",\"arv_time\":\"06:05 PM\",\"fare\":\"108111\"},{\"id\":2,\"from\":\"Delhi (DEL)\",\"to\":\"Dubai (DXB)\",\"name\":\"IndiGo\",\"fno\":\"1461\",\"dep_date\":\"08 Sep 2023\",\"arv_date\":\"08 Sep 2023\",\"dep_time\":\"08:40 AM\",\"arv_time\":\"10:50 AM\",\"fare\":0},{\"id\":3,\"from\":\"Dubai (DXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"1464\",\"dep_date\":\"16 Sep 2023\",\"arv_date\":\"17 Sep 2023\",\"dep_time\":\"08:50 PM\",\"arv_time\":\"01:50 AM\",\"fare\":0},{\"id\":4,\"from\":\"Delhi (DEL)\",\"to\":\"Ranchi (IXR)\",\"name\":\"IndiGo\",\"fno\":\"5037\",\"dep_date\":\"17 Sep 2023\",\"arv_date\":\"17 Sep 2023\",\"dep_time\":\"05:35 AM\",\"arv_time\":\"07:30 AM\",\"fare\":0},{\"id\":5,\"from\":\"Bagdogra (IXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"534\",\"dep_date\":\"07 Sep 2023\",\"arv_date\":\"07 Sep 2023\",\"dep_time\":\"04:45 PM\",\"arv_time\":\"07:00 PM\",\"fare\":null},{\"id\":6,\"from\":\"Delhi (DEL)\",\"to\":\"Dubai (DXB)\",\"name\":\"IndiGo\",\"fno\":\"1461\",\"dep_date\":\"08 Sep 2023\",\"arv_date\":\"08 Sep 2023\",\"dep_time\":\"08:40 AM\",\"arv_time\":\"10:50 AM\",\"fare\":0},{\"id\":7,\"from\":\"Dubai (DXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"IndiGo\",\"fno\":\"1464\",\"dep_date\":\"16 Sep 2023\",\"arv_date\":\"17 Sep 2023\",\"dep_time\":\"08:50 PM\",\"arv_time\":\"01:50 AM\",\"fare\":0},{\"id\":8,\"from\":\"Delhi (DEL)\",\"to\":\"Bagdogra (IXB)\",\"name\":\"IndiGo\",\"fno\":\"5174\",\"dep_date\":\"17 Sep 2023\",\"arv_date\":\"17 Sep 2023\",\"dep_time\":\"07:30 AM\",\"arv_time\":\"09:35 AM\",\"fare\":0}]', '[]', '[{\"id\":0,\"check_in\":\"08\\/09\\/2023\",\"city\":\"DUBAI\",\"hotel_name\":\"Hotel The Canvas Dubai - MGallery\",\"room_type\":\"Superior Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":4,\"check_out\":\"12\\/09\\/2023\",\"rate\":\"27039\"},{\"id\":1,\"check_in\":\"12\\/09\\/2023\",\"check_out\":\"13\\/09\\/2023\",\"city\":\"DUBAI\",\"hotel_name\":\"Hotel Atlantis, The Palm\",\"room_type\":\"Imperial Club King Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"rate\":\"58418\"},{\"id\":2,\"check_in\":\"13\\/09\\/2023\",\"city\":\"DUBAI\",\"rate\":\"26032\",\"hotel_name\":\"Hotel Park Regis Kris Kin\",\"room_type\":\"Superior Room - Triple Beds\",\"rooms\":1,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"16\\/09\\/2023\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are subject to availability at the time of confirmation.</li>\n	<li>In case of unavailability in the listed hotels, arrangement for an alternate accommodation will be made in a hotel of similar standard.</li>\n	<li>There will be no refund for unused nights or early check-out (In case of Medical condition it completely depends on hotel policy).</li>\n	<li>Check-in and check-out times at hotels would be as per hotel policies. Early check-in or late check-out is subject to availability and may be chargeable by the hotel.</li>\n	<li>The price does not include expenses of personal nature, such as laundry, telephone calls, room service, alcoholic beverages, mini bar charges, tips, portage, camera fees etc.</li>\n	<li>Multi Zone Travels reserves the right to modify the itinerary at any point, due to reasons including but not limited to: Force Majeure events, strikes, fairs, festivals, weather conditions, traffic problems, overbooking of hotels / flights, cancellation / re-routing of flights, closure of / entry restrictions at a place of visit, etc. While we will do our best to make suitable alternate arrangements, we would not be held liable for any refunds/compensation claims arising out of this.</li>\n	<li>In case a flight gets cancelled, Multi Zone Travels will not be liable to provide any alternate flights within the same cost, any additional cost incurred for the same shall be borne by the traveller.</li>\n	<li>For more details click <a href=\"https://res.cloudinary.com/anilsam90/image/upload/v1534070888/terms.pdf\" target=\"_blank\">here</a></li>\n</ul>', '[]', '<ul>\n	<li>Return Airfare <strong>Ex-Ranchi </strong><em>for 01 Pax&nbsp;</em><strong>/ Ex-Bagdogra </strong><em>for 02&nbsp;Pax</em><strong>.</strong></li>\n	<li><strong>04&nbsp;Nights</strong> Accommodation in<strong> Hotel&nbsp;The Canvas Dubai - MGallery.</strong></li>\n	<li><strong>01&nbsp;Night</strong>&nbsp;Accommodation in<strong> Hotel&nbsp;Atlantis, The Palm.</strong></li>\n	<li><strong>03&nbsp;Nights</strong> Accommodation in<strong> Hotel&nbsp;Park Regis Kris Kin.</strong></li>\n	<li><strong>Daily Breakfast </strong>at the Hotel.</li>\n	<li><strong>Dubai Airport transfers</strong> on PVT.</li>\n	<li><strong>Inter Hotel Transfer</strong> <em>(Hotel The Canvas -&nbsp;Hotel Atlantis)&nbsp;</em>on PVT.</li>\n	<li><strong>Inter Hotel Transfer</strong> <em>(Hotel Atlantis - Hotel Park Regis&nbsp;)&nbsp;</em>on PVT.</li>\n	<li><strong>Half-Day Dubai City Tour</strong> with&nbsp;<strong>Dubai Mall</strong>&nbsp;&amp;<strong> Fountain Show </strong>on SIC.</li>\n	<li><strong>Burj Khalifa 124th&nbsp;Floor</strong> on SIC.</li>\n	<li><strong>DELUXE Marina Dhow Cruise </strong>on SIC.</li>\n	<li><strong>PREMIUM Desert Safari </strong>with BBQ Dinner, Belly Dance Show, Tanoura Show, and other camp activities on SIC.&nbsp;</li>\n	<li><strong>Abu Dhabi City Tour with Ferrari World Theme Park</strong> with a visit to <strong>Grand Mosque</strong> on PVT.</li>\n	<li><strong>Warner Bros.</strong> on PVT.</li>\n	<li><strong>Aqua Venture &amp; Lost Chambers </strong>on PVT.</li>\n	<li><strong>Dubai Frame</strong>&nbsp;on PVT.</li>\n	<li><b>Museum of the Future&nbsp;</b>on PVT.</li>\n	<li><strong>Sky View Glass Slide</strong> 01 Time on PVT.</li>\n	<li><strong>Dubai Tourist Visa </strong>+ Basic Insurance.</li>\n</ul>', '<ul>\n	<li>Mandatory Tourism Dirham Fee Applicable @ <strong>20-30 AED</strong> Per Room Per Night.</li>\n	<li>Any kind of personal expenses.</li>\n	<li>Tips, Insurance, Laundry, Phone Calls, Guide Fee &amp; Camera Fee.</li>\n	<li>Anything not mentioned in the inclusions above.</li>\n</ul>', NULL, NULL, '{\"profit_percent\":null,\"package\":{\"flight_cost\":108111,\"hotel_cost\":111489,\"land_cost\":\"117810\",\"visa_cost\":\"19500\"},\"extra\":[],\"cost_price\":356910,\"amount_of_percent\":\"Rs 0\",\"selling_price\":435000,\"profit_figure\":\"78090\",\"percent_of_amount\":\"21.00%\"}', 'MZQ/0372/072023', 435000, 145000, 34500, '2023-07-17 08:15:14', '2023-09-03 11:31:17', 0, 1, NULL, 0, 0);
