(460, 'MR. PRASANT CHHETRI', NULL, '9955334161', 'info@multizonetravels.com', 'THAILAND', '2024-02-12', 5, 0, 5, '[]', '[{\"id\":1,\"from\":\"Ranchi (IXR)\",\"to\":\"Mumbai (BOM)\",\"name\":\"IndiGo\",\"fno\":\"298\",\"dep_date\":\"12 Feb 2024\",\"arv_date\":\"12 Feb 2024\",\"dep_time\":\"03:55 PM\",\"arv_time\":\"06:20 PM\",\"fare\":88170},{\"id\":2,\"from\":\"Mumbai (BOM)\",\"to\":\"Phuket (HKT)\",\"name\":\"IndiGo\",\"fno\":\"1071\",\"dep_date\":\"13 Feb 2024\",\"arv_date\":\"13 Feb 2024\",\"dep_time\":\"04:05 AM\",\"arv_time\":\"10:05 AM\",\"fare\":0},{\"id\":3,\"from\":\"Phuket (HKT)\",\"to\":\"Bangkok (DMK)\",\"name\":\"Thai Lion Air\",\"fno\":\"1753\",\"dep_date\":\"16 Feb 2024\",\"arv_date\":\"16 Feb 2024\",\"dep_time\":\"06:40 AM\",\"arv_time\":\"08:00 AM\",\"fare\":25405},{\"id\":4,\"from\":\"Bangkok (BKK)\",\"to\":\"Kolkata (CCU)\",\"name\":\"IndiGo\",\"fno\":\"59\",\"dep_date\":\"19 Feb 2024\",\"arv_date\":\"19 Feb 2024\",\"dep_time\":\"02:55 AM\",\"arv_time\":\"04:15 AM\",\"fare\":69815},{\"id\":5,\"from\":\"Kolkata (CCU)\",\"to\":\"Ranchi (IXR)\",\"name\":\"IndiGo\",\"fno\":\"7561\",\"dep_date\":\"19 Feb 2024\",\"arv_date\":\"19 Feb 2024\",\"dep_time\":\"06:55 AM\",\"arv_time\":\"08:10 AM\",\"fare\":0}]', '[]', '[{\"id\":0,\"check_in\":\"13\\/02\\/2024\",\"hotel_name\":\"Hotel The ASHLEE Plaza Patong Hotel & Spa\",\"room_type\":\"Deluxe Room\",\"city\":\"PHUKET\",\"rooms\":2,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"16\\/02\\/2024\",\"rate\":\"56097\"},{\"id\":1,\"check_in\":\"16\\/02\\/2024\",\"city\":\"PATTAYA\",\"hotel_name\":\"Hotel GLOW\",\"room_type\":\"Deluxe Room\",\"rooms\":2,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"17\\/02\\/2024\",\"rate\":\"7405\"},{\"id\":2,\"check_in\":\"17\\/02\\/2024\",\"city\":\"BANGKOK\",\"rate\":\"8043\",\"room_type\":\"Deluxe Room\",\"hotel_name\":\"Hotel Anya Nana @ Sukhumvit\",\"rooms\":2,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"18\\/02\\/2024\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are sub