LL, NULL, '{\"profit_percent\":\"12\",\"package\":{\"flight_cost\":54252,\"land_cost\":\"81500\"},\"extra\":[],\"cost_price\":135752,\"amount_of_percent\":\"Rs 16290.24\",\"selling_price\":152042.23999999999068677425384521484375,\"profit_figure\":\"00\",\"percent_of_amount\":\"0.00%\"}', 'MZQ/0481/032024', 152600, 76300, 31600, '2024-03-09 09:47:35', '2024-05-14 07:33:14', 0, 1, NULL, 0, 0),
(489, 'Mr Aman', 'CDG', '9810621916', 'info@multizonetravels.com', 'Turkey & Dubai', '2024-09-05', 10, 0, 2, '[]', '[{\"id\":1,\"from\":\"Delhi (DEL)\",\"to\":\"Istanbul (IST)\",\"name\":\"IndiGo\",\"fno\":\"11\",\"dep_date\":\"05 Sep 2024\",\"arv_date\":\"05 Sep 2024\",\"dep_time\":\"06:35 AM\",\"arv_time\":\"11:15 AM\",\"fare\":24688},{\"id\":2,\"from\":\"Istanbul (IST)\",\"to\":\"Dubai (DXB)\",\"name\":\"FlyDubai Airways\",\"fno\":\"756\",\"dep_date\":\"12 Sep 2024\",\"arv_date\":\"12 Sep 2024\",\"dep_time\":\"02:10 AM\",\"arv_time\":\"07:35 AM\",\"fare\":41550},{\"id\":3,\"from\":\"Dubai (DXB)\",\"to\":\"Delhi (DEL)\",\"name\":\"SpiceJet\",\"fno\":\"6\",\"dep_date\":\"15 Sep 2024\",\"arv_date\":\"15 Sep 2024\",\"dep_time\":\"11:10 AM\",\"arv_time\":\"03:55 PM\",\"fare\":16772}]', '[]', '[{\"id\":0,\"check_in\":\"05\\/09\\/2024\",\"hotel_name\":\"Hotel Metropolitan Taksim\",\"city\":\"ISTANBUL\",\"room_type\":\"Standard Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"08\\/09\\/2024\"},{\"id\":1,\"check_in\":\"08\\/09\\/2024\",\"city\":\"ANTALYA\",\"hotel_name\":\"Hotel Ring Downtown\",\"room_type\":\"Standard Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"11\\/09\\/2024\"},{\"id\":2,\"check_in\":\"11\\/09\\/2024\",\"city\":\"ISTANBUL\",\"hotel_name\":\"Hotel Metropolitan Taksim\",\"room_type\":\"Standard Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"12\\/09\\/2024\"},{\"id\":3,\"check_in\":\"12\\/09\\/2024\",\"city\":\"DUBAI\",\"hotel_name\":\"Hotel Majestic City Retreat\",\"room_type\":\"Double Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":3,\"check_out\":\"15\\/09\\/2024\",\"rate\":\"13400\"}]', '<ul>\n	<li>Airline seats/fare and hotel rooms are subject to availability at the time of confirmation.</li>\n	<li>In case of unavailability in the listed hotels, arrangement for an alternate accommodation will be made in a hotel of similar standard.</li>\n	<li>There will be no refund for unused nights or early check-ou