ul>', NULL, NULL, '{\"profit_percent\":\"15\",\"package\":{\"flight_cost\":0,\"land_cost\":\"182025\"},\"extra\":[],\"cost_price\":182025,\"amount_of_percent\":\"Rs 27303.75\",\"selling_price\":209328.75}', 'MZQ/0673/052025', 209328, 29904, 0, '2025-05-02 07:40:04', '2025-05-02 13:37:29', 0, 1, NULL, 0, 0),
