(837, 'Mr. Premjeet Kumar', 'Prince Motors', '8434445006', 'info@multizonetravels.com', 'MALDIVES', '2026-05-04', 4, 1, 2, '[]', '[{\"id\":1,\"from\":\"Ranchi (IXR)\",\"to\":\"Mumbai (BOM)\",\"name\":\"IndiGo\",\"fno\":\"938\",\"dep_date\":\"04 May 2026\",\"arv_date\":\"04 May 2026\",\"dep_time\":\"11:05 AM\",\"arv_time\":\"01:25 PM\",\"fare\":64152},{\"id\":2,\"from\":\"Mumbai (BOM)\",\"to\":\"Male (MLE)\",\"name\":\"IndiGo\",\"fno\":\"1131\",\"dep_date\":\"05 May 2026\",\"arv_date\":\"05 May 2026\",\"dep_time\":\"10:50 AM\",\"arv_time\":\"01:10 PM\",\"fare\":0},{\"id\":3,\"from\":\"Male (MLE)\",\"to\":\"Bangalore (BLR)\",\"name\":\"IndiGo\",\"fno\":\"1128\",\"dep_date\":\"09 May 2026\",\"arv_date\":\"09 May 2026\",\"dep_time\":\"03:15 PM\",\"arv_time\":\"05:40 PM\",\"fare\":68601},{\"id\":4,\"from\":\"Bangalore (BLR)\",\"to\":\"Ranchi (IXR)\",\"name\":\"AirIndiaExpress\",\"fno\":\"2053\",\"dep_date\":\"10 May 2026\",\"arv_date\":\"10 May 2026\",\"dep_time\":\"01:55 PM\",\"arv_time\":\"04:20 PM\",\"fare\":\"28350\"}]', '[]', '[{\"id\":0,\"check_in\":\"04\\/05\\/2026\",\"hotel_name\":\"Hotel Sahara Star\",\"city\":\"MUMBAI\",\"rate\":\"10500\",\"room_type\":\"Mercury City Room\",\"rooms\":1,\"meal\":\"cp\",\"nights\":1,\"check_out\":\"05\\/05\\/2026\"},{\"id\":1,\"check_in\":\"05\\/05\\/2026\",\"city\":\"MALDIVES\",\"hotel_name\":\"Hotel Holiday Inn Resort\",\"meal\":\"map\",\"room_type\":\"Beach Villa\",\"rooms\":1,\"nights\":2,\"check_out\":\"07\\/05\\/2026\",\"rate\":\"155000\"},{\"id\":2,\"check_in\":\"07\\/05\\/2026\",\"city\":\"MALDIVES\",\"hotel_name\":\"Hotel Holiday Inn Resort Kandooma\",\"room_type\":\"Overwater Villa Sea view\",\"check_out\":\"09\\/05\\/2026\",\"nights\":2,\"rooms\":1,\"meal\":\"map\",\"rate\":\"00\"},{\"id\":3,\"check_in\":\"09\\/05\\/2026\",\"room_type\":\"Superior Room\",\"check_out\":\"10\\/05\\/2026\",\"nights\":1,\"city\":\"BANGALORE\",\"hotel_name\":\"Hotel Holiday Inn Resort Kandooma\",\"rooms\":1,\"meal\":\"cp\",\"rate\":\"8900\"