(859, 'Ms Puja Sharma', 'BNI EXPLORERS', '9204055682', 'info@multizonetravels.com', 'Spiritual Gujrat 4*', '2026-07-04', 6, 0, 6, '[{\"title\":\"Day\",\"day\":1,\"index\":0,\"image\":null,\"caption\":\"Arrival Ahmedabad\",\"date\":\"04-07-2026 Saturday\",\"todo\":\"<p>Upon arrival at Ahmedabad Airport, transfer to the hotel and relax.<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Ahmedabad<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":2,\"index\":1,\"image\":null,\"caption\":\"Ahmedabad \\u2013 Dwarka\",\"date\":\"05-07-2026 Sunday\",\"todo\":\"<p>After breakfast, proceed to Dwarka. Upon arrival, check in to the hotel and spend the evening at leisure.<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Dwarka<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":3,\"index\":2,\"image\":null,\"caption\":\"Dwarka Sightseeing\",\"date\":\"06-07-2026 Monday\",\"todo\":\"<p>After breakfast, explore the sacred city of Dwarka.<\\/p>\\n\\n<p>Sightseeing Includes:<br \\/>\\n\\u2022 Dwarkadhish Temple<br \\/>\\n\\u2022 Rukmini Devi Temple<br \\/>\\n\\u2022 Nageshwar Jyotirlinga<br \\/>\\n\\u2022 Bet Dwarka<br \\/>\\n\\u2022 Gomti Ghat<br \\/>\\n\\u2022 Sudama Setu<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Dwarka<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":4,\"index\":3,\"image\":null,\"caption\":\"Dwarka \\u2013 Somnath\",\"date\":\"07-07-2026 Tuesday\",\"todo\":\"<p>After breakfast, proceed to Somnath. En route, visit Porbandar, the birthplace of Mahatma Gandhi.<\\/p>\\n\\n<p>Sightseeing Includes:<br \\/>\\n\\u2022 Kirti Mandir, Porbandar<br \\/>\\n\\u2022 Somnath Temple<br \\/>\\n\\u2022 Triveni Sangam<br \\/>\\n\\u2022 Bhalka Tirth<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Somnath<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":5,\"index\":4,\"image\":null,\"caption\":\"Somnath \\u2013 Diu\",\"date\":\"08-07-2026 Wednesday\",\"todo\":\"<p>After breakfast, proceed to Diu and enjoy local sightseeing.<\\/p>\\n\\n<p>Sightseeing Includes:<br \\/>\\n\\u2022 Diu Fort<br \\/>\\n\\u2022 St. Paul\'s Church<br \\/>\\n\\u2022 Naida Caves<br \\/>\\n\\u2022 Nagoa Beach<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Diu<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":6,\"index\":5,\"image\":null,\"caption\":\"Diu \\u2013 Vadodara\",\"date\":\"09-07-2026 Thursday\",\"todo\":\"<p>After breakfast, proceed to Ahmedabad.<\\/p>\\n\\n<p>Sightseeing Includes:<br \\/>\\n\\u2022 Sabarmati Ashram<br \\/>\\n\\u2022 Adalaj Stepwell<\\/p>\\n\\n<p><strong>\\ud83c\\udfe8 Overnight Stay in Ahmedabad<\\/strong><\\/p>\"},{\"title\":\"Day\",\"day\":7,\"index\":6,\"image\":null,\"caption\":\"Departure Ahmedabad\",\"date\":\"10-07-2026 Friday\",\"todo\":\"<p>After breakfast, check out from the hotel and proceed to Ahmedabad Airport for your onward journey.<\\/p>\\n\\n<p><strong>\\u2708\\ufe0f Tour Concludes with Wonderful Memories.<\\/strong><\\/p>\"}]', '[{\"id\":1,\"from\":\"Ranchi (IXR)\",\"to\":\"Ahmedabad (AMD)\",\"name\":\"IndiGo\",\"fno\":\"6654\",\"dep_date\":\"04 Jul 2026\",\"arv_date\":\"04 Jul 2026\",\"dep_time\":\"07:50 PM\",\"arv_time\":\"10:05 PM\",\"fare\":\"67292\"},{\"id\":2,\"from\":\"Ahmedabad (AMD)\",\"to\":\"Ranchi (IXR)\",\"name\":\"IndiGo\",\"fno\":\"6493\",\"dep_date\":\"10 Jul 2026\",\"arv_date\":\"10 Jul 2026\",\"dep_time\":\"11:15 AM\",\"arv_time\":\"01:25 PM\",\"fare\":null},{\"id\":3,\"from\":\"Pune (PNQ)\",\"to\":\"Ahmedabad (AMD)\",\"name\":\"Akasa Air\",\"fno\":\"1916\",\"dep_date\":\"04 Jul 2026\",\"arv_date\":\"04 Jul 2026\",\"dep_time\":\"05:55 PM\",\"arv_time\":\"07:25 PM\",\"fare\":\"3456\"},{\"id\":4,\"from\":\"Ahmedabad (AMD)\",\"to\":\"Pune (PNQ)\",\"name\":\"IndiGo\",\"fno\":\"522\",\"dep_date\":\"10 Jul 2026\",\"arv_date\":\"10 Jul 2026\",\"dep_time\":\"01:55 PM\",\"arv_time\":\"03:10 PM\",\"fare\":\"3702\"}]', '[]', '[{\"id\":0,\"check_in\":\"04\\/07\\/2026\",\"city\":\"Ahmedabad\",\"hotel_name\":\"Hotel Radisson Blu\",\"room_type\":\"Superior Room\",\"rooms\":3,\"meal\":\"cp\",\"nights\